  safePoint(x, z, margin = 5) {
    if (Math.hypot(x, z) < 15) return false;
    if (this.regionId === 'valdoria' && Math.hypot(x - 58, z + 38) < 18) return false;
    if (this.regionId === 'valdoria' && Math.hypot(x + 60, z - 54) < 24) return false;
    if (this.regionId === 'drakmor' && Math.hypot(x - 25, z + 30) < 25) return false;
    if (this.regionId === 'drakmor' && Math.hypot(x + 58, z - 48) < 14) return false;
    if (this.regionId === 'kansordore' && Math.hypot(x, z) < 23) return false;
    if (this.regionId === 'kansordore' && Math.hypot(x, z + 62) < 18) return false;
    if (this.regionId === 'kansordore' && Math.hypot(x + 56, z - 48) < 14) return false;
    for (const c of this.colliders) {
      if (Math.hypot(x - c.x, z - c.z) < c.r + margin) return false;
    }
    return true;
  }

  scatterTrees(count, kind) {
    const p = this.region.palette;
    const trunkGeo = new THREE.CylinderGeometry(0.18, 0.32, 3.2, 6);
    const trunkMat = standardMaterial('#5b4131');
    const canopyGeo = new THREE.IcosahedronGeometry(1.35, 0);
    const canopyMat = new THREE.MeshToonMaterial({ color: '#ffffff', gradientMap: toonGradient(), vertexColors: false });
    const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, count);
    const canopies = new THREE.InstancedMesh(canopyGeo, canopyMat, count * 3);
    trunks.castShadow = true;
    trunks.receiveShadow = true;
    canopies.castShadow = true;
    canopies.receiveShadow = true;
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    let ci = 0;
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 170;
        z = (this.rng() - 0.5) * 170;
        tries++;
      } while (!this.safePoint(x, z, 6) && tries < 30);
      const y = this.heightAt(x, z);
      const s = 0.7 + this.rng() * 0.9;
      dummy.position.set(x, y + 1.6 * s, z);
      dummy.rotation.set(0, this.rng() * TAU, 0);
      dummy.scale.set(s, s, s);
      dummy.updateMatrix();
      trunks.setMatrixAt(i, dummy.matrix);
      for (let j = 0; j < 3; j++) {
        const cs = (0.65 + this.rng() * 0.5) * s;
        dummy.position.set(x + (this.rng() - 0.5) * 1.1, y + (2.8 + this.rng() * 1.2) * s, z + (this.rng() - 0.5) * 1.1);
        dummy.rotation.set(this.rng() * 0.4, this.rng() * TAU, this.rng() * 0.4);
        dummy.scale.set(cs, cs * (0.8 + this.rng() * 0.3), cs);
        dummy.updateMatrix();
        canopies.setMatrixAt(ci, dummy.matrix);
        const hue = 0.24 + this.rng() * 0.08;
        color.setHSL(hue, 0.35 + this.rng() * 0.15, 0.32 + this.rng() * 0.14);
        canopies.setColorAt(ci, color);
        ci++;
      }
      this.addCollider(x, z, 0.55 * s);
    }
    this.scene.add(trunks, canopies);
    this.dynamic.push({ type: 'trees', mesh: canopies, phase: this.rng() * TAU });
  }

  scatterDeadTrees(count) {
    const trunkMat = standardMaterial('#2a1e20');
    const group = new THREE.Group();
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 170;
        z = (this.rng() - 0.5) * 170;
        tries++;
      } while (!this.safePoint(x, z, 5) && tries < 30);
      const y = this.heightAt(x, z);
      const s = 0.8 + this.rng() * 0.9;
      const trunk = cyl(0.08, 0.3, 3.8 * s, trunkMat, 5);
      trunk.position.set(x, y + 1.9 * s, z);
      trunk.rotation.z = (this.rng() - 0.5) * 0.3;
      group.add(trunk);
      for (let j = 0; j < 3; j++) {
        const branch = cyl(0.03, 0.1, 1.5 * s, trunkMat, 4);
        branch.position.set(x + (this.rng() - 0.5) * 0.8, y + 3.0 * s, z + (this.rng() - 0.5) * 0.8);
        branch.rotation.z = (this.rng() - 0.5) * 1.8;
        branch.rotation.x = (this.rng() - 0.5) * 1.8;
        group.add(branch);
      }
      this.addCollider(x, z, 0.4);
    }
    this.scene.add(group);
  }

  scatterCrystalTrees(count) {
    const trunkMat = standardMaterial('#7e7b9e');
    const crystalMat = new THREE.MeshStandardMaterial({
      color: '#c6b7ff', emissive: new THREE.Color('#7a62dc').multiplyScalar(0.4), roughness: 0.25, metalness: 0.2,
    });
    const group = new THREE.Group();
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 170;
        z = (this.rng() - 0.5) * 170;
        tries++;
      } while (!this.safePoint(x, z, 5) && tries < 30);
      const y = this.heightAt(x, z);
      const s = 0.8 + this.rng() * 1.0;
      const trunk = cyl(0.1, 0.2, 3.4 * s, trunkMat, 5);
      trunk.position.set(x, y + 1.7 * s, z);
      group.add(trunk);
      for (let j = 0; j < 3; j++) {
        const crystal = new THREE.Mesh(new THREE.OctahedronGeometry(0.55 * s, 0), crystalMat);
        crystal.position.set(x + (this.rng() - 0.5) * 1.2, y + (3.0 + this.rng() * 0.8) * s, z + (this.rng() - 0.5) * 1.2);
        crystal.rotation.set(this.rng() * TAU, this.rng() * TAU, 0);
        group.add(crystal);
      }
      this.addCollider(x, z, 0.5);
    }
    this.scene.add(group);
  }

  scatterRocks(count) {
    const geo = new THREE.DodecahedronGeometry(0.8, 0);
    const mat = new THREE.MeshToonMaterial({ color: this.regionId === 'drakmor' ? '#3b2d31' : '#8b877a', gradientMap: toonGradient() });
    const rocks = new THREE.InstancedMesh(geo, mat, count);
    rocks.castShadow = true;
    rocks.receiveShadow = true;
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 160;
        z = (this.rng() - 0.5) * 160;
        tries++;
      } while (!this.safePoint(x, z, 4) && tries < 25);
      const y = this.heightAt(x, z);
      const s = 0.4 + this.rng() * 1.4;
      dummy.position.set(x, y + s * 0.35, z);
      dummy.rotation.set(this.rng() * TAU, this.rng() * TAU, this.rng() * TAU);
      dummy.scale.set(s, s * (0.6 + this.rng() * 0.6), s);
      dummy.updateMatrix();
      rocks.setMatrixAt(i, dummy.matrix);
      color.setHSL(this.regionId === 'drakmor' ? 0.02 : 0.12, 0.12, 0.28 + this.rng() * 0.16);
      rocks.setColorAt(i, color);
      if (s > 0.85) this.addCollider(x, z, s * 0.8);
    }
    this.scene.add(rocks);
  }

  scatterGrass(count, color) {
    const geo = new THREE.ConeGeometry(0.09, 0.55, 3);
    const mat = new THREE.MeshToonMaterial({ color: '#ffffff', gradientMap: toonGradient() });
    const grass = new THREE.InstancedMesh(geo, mat, count);
    const dummy = new THREE.Object3D();
    const c = new THREE.Color();
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 150;
        z = (this.rng() - 0.5) * 150;
        tries++;
      } while (Math.hypot(x, z) < 14 && tries < 12);
      const y = this.heightAt(x, z);
      dummy.position.set(x, y + 0.25, z);
      dummy.rotation.set(0, this.rng() * TAU, (this.rng() - 0.5) * 0.2);
      const s = 0.6 + this.rng() * 1.1;
      dummy.scale.set(s, s, s);
      dummy.updateMatrix();
      grass.setMatrixAt(i, dummy.matrix);
      c.set(color).offsetHSL((this.rng() - 0.5) * 0.05, 0.05, (this.rng() - 0.5) * 0.12);
      grass.setColorAt(i, c);
    }
    grass.receiveShadow = true;
    this.scene.add(grass);
  }

  scatterFlowers(count) {
    const geo = new THREE.SphereGeometry(0.07, 4, 3);
    const mat = new THREE.MeshBasicMaterial({ color: '#ffffff' });
    const flowers = new THREE.InstancedMesh(geo, mat, count);
    const dummy = new THREE.Object3D();
    const c = new THREE.Color();
    const palette = ['#f4d58d', '#ff8fb1', '#9ef0ff', '#f6f1dc'];
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 110;
        z = (this.rng() - 0.5) * 110;
        tries++;
      } while (Math.hypot(x, z) < 15 && tries < 12);
      const y = this.heightAt(x, z);
      dummy.position.set(x, y + 0.35, z);
      dummy.scale.setScalar(0.8 + this.rng() * 0.8);
      dummy.updateMatrix();
      flowers.setMatrixAt(i, dummy.matrix);
      c.set(palette[Math.floor(this.rng() * palette.length)]);
      flowers.setColorAt(i, c);
    }
    this.scene.add(flowers);
  }

  scatterLavaCracks(count) {
    const mat = new THREE.MeshBasicMaterial({ color: '#ff5b2e' });
    for (let i = 0; i < count; i++) {
      let x, z, tries = 0;
      do {
        x = (this.rng() - 0.5) * 150;
        z = (this.rng() - 0.5) * 150;
        tries++;
      } while (!this.safePoint(x, z, 4) && tries < 25);
      const crack = box(0.12 + this.rng() * 0.2, 0.02, 2 + this.rng() * 5, mat);
      crack.position.set(x, this.heightAt(x, z) + 0.05, z);
      crack.rotation.y = this.rng() * TAU;
      this.scene.add(crack);
    }
  }

  scatterFloatingRocks(count) {
    for (let i = 0; i < count; i++) {
      const x = (this.rng() - 0.5) * 130;
      const z = (this.rng() - 0.5) * 130;
      const y = this.heightAt(x, z) + 4 + this.rng() * 12;
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.6 + this.rng() * 1.4, 0),
        standardMaterial('#a9a5c2', { roughness: 0.9 }),
      );
      rock.position.set(x, y, z);
      rock.rotation.set(this.rng() * TAU, this.rng() * TAU, this.rng() * TAU);
      this.scene.add(rock);
      this.dynamic.push({ type: 'floatingRock', mesh: rock, baseY: y, phase: this.rng() * TAU, speed: 0.3 + this.rng() * 0.5 });
      addGlow(rock, '#9ef0ff', 2.4, [0, 0, 0], 0.12);
    }
  }

  /* ------------------------------------------------------------------ */
  /* Interactables                                                       */
  /* ------------------------------------------------------------------ */

  addChest(x, z, id, loot) {
    const y = this.heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z);
    const wood = standardMaterial('#6b442d');
    const gold = standardMaterial('#d8bd77', { metalness: 0.6, roughness: 0.3 });
    const base = box(1.1, 0.7, 0.75, wood);
    base.position.y = 0.45;
    g.add(base);
    const lid = box(1.15, 0.32, 0.8, wood);
    lid.position.y = 0.95;
    lid.rotation.x = 0;
    g.add(lid);
    for (const s of [-1, 1]) {
      const band = box(0.1, 0.82, 0.82, gold);
      band.position.set(s * 0.38, 0.55, 0);
      g.add(band);
    }
    const lock = box(0.18, 0.24, 0.08, gold);
    lock.position.set(0, 0.6, 0.4);
    g.add(lock);
    addGlow(g, '#f4d58d', 1.8, [0, 0.9, 0], 0.25);
    this.scene.add(g);
    this.interactables.push({ id, type: 'chest', x, z, radius: 2.6, label: 'Cofre antiguo', mesh: g, lid, opened: false, loot });
    this.addCollider(x, z, 0.8);
  }

  addBrazier(x, z, id) {
    const y = this.heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z);
    const stone = standardMaterial('#7a7264');
    const base = cyl(0.45, 0.65, 0.9, stone, 6);
    base.position.y = 0.45;
    g.add(base);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.65, 0.4, 0.38, 8, 1, true), stone);
    bowl.position.y = 1.0;
    g.add(bowl);
    const flame = glowSprite('#ffb347', 1.8, 0.0);
    flame.position.y = 1.3;
    g.add(flame);
    this.scene.add(g);
    this.interactables.push({ id, type: 'brazier', x, z, radius: 2.5, label: 'Brasero dormido', mesh: g, flame, lit: false });
    this.addCollider(x, z, 0.7);
  }

  addLamp(x, z, id, label) {
    const y = this.heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z);
    const stone = standardMaterial('#8d8978');
    const base = cyl(0.6, 0.9, 0.5, stone, 6);
    base.position.y = 0.25;
    g.add(base);
    const stem = cyl(0.18, 0.28, 1.2, stone, 6);
    stem.position.y = 1.1;
    g.add(stem);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.35, 0.4, 8, 1, true), stone);
    bowl.position.y = 1.75;
    g.add(bowl);
    const flame = glowSprite('#9ef0ff', 2.2, 0.0);
    flame.position.y = 2.1;
    g.add(flame);
    this.scene.add(g);
    const item = { id, type: 'lamp', x, z, radius: 2.8, label, mesh: g, flame, lit: false };
    this.interactables.push(item);
    this.addCollider(x, z, 0.8);
    return { group: g, item };
  }

  addCampfire(x, z) {
    const y = this.heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z);
    const stone = standardMaterial('#6f6a5c');
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU;
      const s = sphere(0.2, stone, 5);
      s.position.set(Math.cos(a) * 0.8, 0.2, Math.sin(a) * 0.8);
      g.add(s);
    }
    const flame = glowSprite('#ffb347', 2.2, 0.7);
    flame.position.y = 0.8;
    g.add(flame);
    this.dynamic.push({ type: 'fire', mesh: flame, phase: 0 });
    this.scene.add(g);
  }

  addWaystone(x, z, id, name) {
    const y = this.heightAt(x, z);
    const g = new THREE.Group();
    g.position.set(x, y, z);
    const stone = standardMaterial('#8d8978');
    const base = cyl(1.3, 1.6, 0.5, stone, 6);
    base.position.y = 0.25;
    g.add(base);
    const obelisk = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.62, 3.6, 4), stone);
    obelisk.position.y = 2.1;
    obelisk.rotation.y = Math.PI / 4;
    g.add(obelisk);
    const rune = new THREE.Mesh(new THREE.OctahedronGeometry(0.28, 0), new THREE.MeshBasicMaterial({ color: '#7ee8fa' }));
    rune.position.y = 4.1;
    g.add(rune);
    addGlow(g, '#7ee8fa', 2.8, [0, 4.1, 0], 0.5);
    this.scene.add(g);
    this.interactables.push({ id, type: 'waystone', x, z, radius: 3, label: name, mesh: g, rune });
    this.addCollider(x, z, 1.2);
  }

  buildWaystones() {
    if (this.regionId === 'valdoria') {
      this.addWaystone(0, 16, 'waystone_val', 'Altar de Resonancia');
    } else if (this.regionId === 'drakmor') {
      this.addWaystone(-58, 53, 'waystone_drak', 'Altar de Ceniza');
    } else {
      this.addWaystone(-56, 53, 'waystone_kan', 'Altar de los Ecos');
    }
  }

  buildLore() {
    for (const l of LORE) {
      if (l.region !== this.regionId) continue;
      const y = this.heightAt(l.pos.x, l.pos.z);
      const g = new THREE.Group();
      g.position.set(l.pos.x, y, l.pos.z);
      const book = box(0.7, 0.1, 0.5, standardMaterial('#efe4c9'));
      book.position.y = 1.2;
      book.rotation.x = 0.15;
      g.add(book);
      const cover = box(0.74, 0.04, 0.54, standardMaterial('#7a4b3a'));
      cover.position.y = 1.14;
      cover.rotation.x = 0.15;
      g.add(cover);
      const glow = addGlow(g, '#f4d58d', 2.2, [0, 1.2, 0], 0.5);
      glow.material.opacity = 0.4;
      this.dynamic.push({ type: 'lore', mesh: g, baseY: y, phase: this.rng() * TAU });
      this.scene.add(g);
      this.interactables.push({ id: l.id, type: 'lore', x: l.pos.x, z: l.pos.z, radius: 2.6, label: l.name, mesh: g, data: l });
      this.addCollider(l.pos.x, l.pos.z, 0.4);
    }
  }

  /* ------------------------------------------------------------------ */
  /* Runtime                                                             */
  /* ------------------------------------------------------------------ */

  addQuestMarker() {
    const marker = createQuestMarker('#f4d58d');
    marker.visible = false;
    this.scene.add(marker);
    this.questMarker = marker;
    return marker;
  }

  setQuestTarget(pos, label = '') {
    if (!this.questMarker) this.addQuestMarker();
    if (!pos) {
      this.questMarker.visible = false;
      return;
    }
    this.questMarker.position.set(pos.x, this.heightAt(pos.x, pos.z) + 4.2, pos.z);
    this.questMarker.visible = true;
    this.questMarker.userData.label = label;
  }

  update(dt) {
    this.time += dt;
    const t = this.time;
    if (this.water) this.water.material.uniforms.uTime.value = t;
    if (this.motes) {
      const arr = this.motes.positions;
      for (let i = 0; i < this.motes.seeds.length; i++) {
        const s = this.motes.seeds[i];
        arr[i * 3 + 1] = s.base + Math.sin(t * s.speed + s.phase) * 1.6;
        arr[i * 3] = s.x + Math.cos(t * s.speed * 0.3 + s.phase) * 0.6;
      }
      this.motes.points.geometry.attributes.position.needsUpdate = true;
    }
    for (const c of this.clouds) {
      c.position.x += dt * 0.55;
      if (c.position.x > 170) c.position.x = -170;
    }
    if (this.stars) this.stars.rotation.y += dt * 0.003;
    for (const d of this.dynamic) {
      if (d.type === 'banner') {
        d.mesh.rotation.y = 0.08 + Math.sin(t * 1.7 + d.phase) * 0.08;
      } else if (d.type === 'lamp') {
        d.mesh.material.opacity = 0.55 + Math.sin(t * 4 + d.phase) * 0.16;
      } else if (d.type === 'fire') {
        d.mesh.material.opacity = 0.5 + Math.sin(t * 7 + d.phase) * 0.22;
        d.mesh.scale.setScalar(1.6 + Math.sin(t * 6 + d.phase) * 0.15);
      } else if (d.type === 'crystal') {
        d.mesh.rotation.y += dt * 0.6;
        d.mesh.position.y = d.baseY + Math.sin(t * 1.5 + d.phase) * 0.22;
      } else if (d.type === 'runeRing') {
        d.mesh.rotation.z += dt * 0.22;
        d.mesh.material.opacity = 0.35 + Math.sin(t * 2.2) * 0.12;
      } else if (d.type === 'archiveCore') {
        d.mesh.rotation.z += dt * 0.18;
        d.mesh.position.y = d.baseY + Math.sin(t * 0.8) * 0.2;
      } else if (d.type === 'orbitRing') {
        d.mesh.rotation.z += dt * d.speed;
        d.mesh.rotation.x = Math.PI / 2 + Math.sin(t * 0.5 + d.phase) * 0.12;
      } else if (d.type === 'floatRune') {
        d.mesh.position.y = d.baseY + Math.sin(t * 1.8 + d.phase) * 0.25;
        d.mesh.rotation.y += dt * 0.9;
      } else if (d.type === 'floatingRock') {
        d.mesh.position.y = d.baseY + Math.sin(t * d.speed + d.phase) * 0.9;
        d.mesh.rotation.y += dt * 0.1;
      } else if (d.type === 'lore') {
        d.mesh.position.y = d.baseY + Math.sin(t * 1.5 + d.phase) * 0.08;
        d.mesh.rotation.y += dt * 0.3;
      } else if (d.type === 'seal') {
        d.mesh.position.y = d.baseY + Math.sin(t * 2 + d.phase) * 0.18;
        d.mesh.rotation.y += dt * 0.7;
        d.ring.rotation.z += dt * 0.5;
      } else if (d.type === 'gateGlow') {
        d.mesh.material.opacity = 0.08 + Math.sin(t * 2) * 0.04;
      }
    }
    if (this.questMarker?.visible) {
      this.questMarker.position.y = this.heightAt(this.questMarker.position.x, this.questMarker.position.z) + 4.2 + Math.sin(t * 2.5) * 0.25;
      this.questMarker.userData.gem.rotation.y += dt * 1.3;
      this.questMarker.userData.ring.rotation.z += dt * 0.7;
      this.questMarker.userData.ring.scale.setScalar(1 + Math.sin(t * 2) * 0.05);
    }
  }

  getEnemySpawns() {
    return this.enemySpawns;
  }

  getCreatureSpawns() {
    return this.creatureSpawns;
  }

  getNpcSpawns() {
    return this.npcSpawns;
  }

  getInteractables() {
    return this.interactables;
  }
}

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

const THEMES = {
  title: {
    bpm: 62,
    root: 50,
    chords: [[0, 4, 7, 11], [-3, 2, 5, 9], [-5, 0, 4, 7], [-1, 4, 7, 11]],
    arp: [0, 7, 4, 11, 7, 14, 11, 4],
    lead: [14, 16, 19, 21, 19, 16, 14, 11],
    pad: 'sine',
    leadWave: 'triangle',
    drums: false,
    brightness: 0.3,
  },
  valdoria: {
    bpm: 76,
    root: 50,
    chords: [[0, 4, 7, 11], [-3, 2, 5, 9], [-5, 0, 4, 7], [-1, 4, 7, 11]],
    arp: [0, 4, 7, 11, 7, 4, 2, 7],
    lead: [7, 9, 11, 14, 12, 11, 9, 7],
    pad: 'sine',
    leadWave: 'triangle',
    drums: false,
    brightness: 0.4,
  },
  drakmor: {
    bpm: 88,
    root: 38,
    chords: [[0, 3, 7, 10], [-2, 1, 5, 8], [-4, 0, 3, 7], [-2, 1, 5, 8]],
    arp: [0, 7, 3, 10, 7, 3, 0, 3],
    lead: [12, 10, 7, 10, 15, 12, 10, 7],
    pad: 'sawtooth',
    leadWave: 'sawtooth',
    drums: true,
    brightness: 0.28,
  },
  kansordore: {
    bpm: 68,
    root: 52,
    chords: [[0, 4, 7, 11], [2, 6, 9, 13], [-3, 2, 5, 9], [-1, 4, 7, 11]],
    arp: [0, 7, 11, 14, 11, 7, 4, 11],
    lead: [19, 21, 23, 26, 23, 21, 19, 16],
    pad: 'sine',
    leadWave: 'sine',
    drums: false,
    brightness: 0.55,
  },
  boss: {
    bpm: 112,
    root: 38,
    chords: [[0, 3, 7, 10], [-1, 2, 6, 9], [-4, 0, 3, 7], [-2, 1, 5, 8]],
    arp: [0, 7, 3, 10, 12, 10, 7, 3],
    lead: [15, 14, 12, 10, 7, 10, 12, 14],
    pad: 'sawtooth',
    leadWave: 'square',
    drums: true,
    brightness: 0.22,
  },
};

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.started = false;
    this.musicVolume = 0.55;
    this.sfxVolume = 0.8;
    this.theme = 'title';
    this.boss = false;
    this.step = 0;
    this.nextNoteTime = 0;
    this.lastUpdate = 0;
    this.noiseBuffer = null;
    this.muted = false;
  }

  async start() {
    if (this.started) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.started = true;
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 1;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 4;
    comp.attack.value = 0.01;
    comp.release.value = 0.25;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = this.musicVolume * 0.32;
    this.musicBus.connect(this.master);

    this.sfxBus = this.ctx.createGain();
    this.sfxBus.gain.value = this.sfxVolume * 0.75;
    this.sfxBus.connect(this.master);

    this.reverb = this.ctx.createConvolver();
    this.reverb.buffer = this.makeImpulse(3.4, 2.2);
    this.reverbGain = this.ctx.createGain();
    this.reverbGain.gain.value = 0.28;
    this.reverb.connect(this.reverbGain);
    this.reverbGain.connect(this.master);

    this.noiseBuffer = this.makeNoise(1.2);
    this.nextNoteTime = this.ctx.currentTime + 0.1;
    this.lastUpdate = this.ctx.currentTime;
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  makeImpulse(seconds, decay) {
    const rate = this.ctx.sampleRate;
    const len = Math.floor(rate * seconds);
    const buf = this.ctx.createBuffer(2, len, rate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buf.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay) * (1 - Math.exp(-i / (rate * 0.02)));
      }
    }
    return buf;
  }

  setMuted(v) {
    this.muted = v;
    if (this.master) this.master.gain.setTargetAtTime(v ? 0 : 1, this.ctx.currentTime, 0.05);
  }

  setMusicVolume(v) {
    this.musicVolume = v;
    if (this.musicBus) this.musicBus.gain.setTargetAtTime(v * 0.32, this.ctx.currentTime, 0.1);
  }

  setSfxVolume(v) {
    this.sfxVolume = v;
    if (this.sfxBus) this.sfxBus.gain.setTargetAtTime(v * 0.75, this.ctx.currentTime, 0.1);
  }

  setTheme(name, boss = false) {
    if (this.theme === name && this.boss === boss) return;
    this.theme = name;
    this.boss = boss;
    this.step = 0;
    this.nextNoteTime = this.ctx ? this.ctx.currentTime + 0.05 : 0;
  }

  update() {
    if (!this.ctx || !this.started) return;
    const now = this.ctx.currentTime;
    const theme = THEMES[this.boss ? 'boss' : this.theme] || THEMES.valdoria;
    const beat = 60 / theme.bpm;
    while (this.nextNoteTime < now + 0.35) {
      this.scheduleStep(theme, this.step, this.nextNoteTime, beat);
      this.nextNoteTime += beat / 2;
      this.step++;
    }
  }

  scheduleStep(theme, step, time, beat) {
    const chordIndex = Math.floor(step / 8) % theme.chords.length;
    const chord = theme.chords[chordIndex];
    const root = theme.root;
    const isBar = step % 8 === 0;
    if (isBar) {
      // warm pad
      for (const interval of chord) {
        this.note(midi(root + interval), time, beat * 3.8, 0.055, theme.pad, 0.55, 0.9);
        this.note(midi(root + interval + 12), time, beat * 3.8, 0.018, theme.pad, 0.7, 1.1);
      }
    }
    // arpeggio
    const arp = theme.arp[step % theme.arp.length];
    const arpOct = step % 16 < 8 ? 12 : 24;
    if (step % 2 === 0 || theme.brightness > 0.5) {
      this.note(midi(root + arp + arpOct), time, beat * 0.42, 0.028 + theme.brightness * 0.02, 'triangle', 0.7, 0.18, true);
    }
    // lead
    if (step % 4 === 0) {
      const lead = theme.lead[(Math.floor(step / 4)) % theme.lead.length];
      this.note(midi(root + lead + 12), time, beat * 1.7, 0.045, theme.leadWave, 0.45, 0.55, true);
    }
    if (theme.drums) {
      if (step % 4 === 0) this.kick(time, 0.18);
      if (step % 4 === 2) this.snare(time, 0.06);
      if (step % 2 === 1) this.hat(time, 0.018);
    }
    if (theme.brightness > 0.45 && step % 8 === 4) {
      this.note(midi(root + 31), time, beat * 2.2, 0.012, 'sine', 0.2, 1.2, true);
    }
  }

  note(freq, time, dur, gain, wave = 'sine', attack = 0.02, release = 0.4, reverb = false) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 900 + this.musicVolume * 1200;
    osc.type = wave;
    osc.frequency.setValueAtTime(freq, time);
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), time + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    osc.connect(filter);
    filter.connect(g);
    g.connect(this.musicBus);
    if (reverb) {
      const send = this.ctx.createGain();
      send.gain.value = 0.35;
      g.connect(send);
      send.connect(this.reverb);
    }
    osc.start(time);
    osc.stop(time + dur + 0.05);
  }

  kick(time, gain = 0.2) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(110, time);
    osc.frequency.exponentialRampToValueAtTime(38, time + 0.18);
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.28);
    osc.connect(g);
    g.connect(this.musicBus);
    osc.start(time);
    osc.stop(time + 0.3);
  }

  snare(time, gain = 0.08) {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 1800;
    f.Q.value = 0.7;
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.16);
    src.connect(f);
    f.connect(g);
    g.connect(this.musicBus);
    src.start(time);
    src.stop(time + 0.2);
  }

  hat(time, gain = 0.02) {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 7000;
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.04);
    src.connect(f);
    f.connect(g);
    g.connect(this.musicBus);
    src.start(time);
    src.stop(time + 0.05);
  }

  tone(freq, dur, opts = {}) {
    if (!this.ctx) return;
    const { type = 'sine', gain = 0.12, slide = 0, delay = 0, filter = 0, reverb = 0.1 } = opts;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = osc;
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filter;
      node.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(this.sfxBus);
    if (reverb) {
      const send = this.ctx.createGain();
      send.gain.value = reverb;
      g.connect(send);
      send.connect(this.reverb);
    }
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise(dur, opts = {}) {
    if (!this.ctx) return;
    const { gain = 0.12, freq = 1800, type = 'bandpass', delay = 0, q = 1, sweep = 0 } = opts;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(60, freq + sweep), t + dur);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(g);
    g.connect(this.sfxBus);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  play(name, opts = {}) {
    if (!this.ctx || this.muted) return;
    const p = opts.pitch || 1;
    switch (name) {
      case 'ui':
        this.tone(520 * p, 0.06, { type: 'sine', gain: 0.06, reverb: 0.1 });
        this.tone(780 * p, 0.09, { type: 'sine', gain: 0.04, delay: 0.03, reverb: 0.1 });
        break;
      case 'swing':
        this.noise(0.18, { gain: 0.11, freq: 2400, sweep: -1700, q: 1.2 });
        this.tone(180 * p, 0.12, { type: 'triangle', gain: 0.035, slide: -60 });
        break;
      case 'heavy':
        this.noise(0.35, { gain: 0.16, freq: 1500, sweep: -1100, q: 0.8 });
        this.tone(95 * p, 0.35, { type: 'sine', gain: 0.16, slide: -40 });
        break;
      case 'hit':
        this.noise(0.12, { gain: 0.12, freq: 500, type: 'lowpass' });
        this.tone(110 * p, 0.16, { type: 'triangle', gain: 0.12, slide: -45 });
        break;
      case 'crit':
        this.noise(0.16, { gain: 0.18, freq: 2600, q: 0.8 });
        this.tone(880 * p, 0.18, { type: 'square', gain: 0.06, slide: 220, reverb: 0.3 });
        break;
      case 'parry':
        this.tone(1320 * p, 0.3, { type: 'triangle', gain: 0.12, slide: 300, reverb: 0.5 });
        this.tone(1980 * p, 0.22, { type: 'sine', gain: 0.07, slide: 420, reverb: 0.5 });
        this.noise(0.15, { gain: 0.1, freq: 5000, type: 'highpass' });
        break;
      case 'block':
        this.noise(0.14, { gain: 0.1, freq: 300, type: 'lowpass' });
        this.tone(160 * p, 0.12, { type: 'triangle', gain: 0.09 });
        break;
      case 'dodge':
        this.noise(0.22, { gain: 0.09, freq: 700, sweep: 900, type: 'bandpass' });
        break;
      case 'spell':
        this.tone(220 * p, 0.6, { type: 'sine', gain: 0.1, slide: 620, reverb: 0.5 });
        this.tone(330 * p, 0.7, { type: 'triangle', gain: 0.07, slide: 880, reverb: 0.6 });
        this.noise(0.5, { gain: 0.05, freq: 1200, sweep: 4000 });
        break;
      case 'ultimate':
        this.tone(110 * p, 1.2, { type: 'sawtooth', gain: 0.12, slide: 440, filter: 1200, reverb: 0.7 });
        this.tone(220 * p, 1.0, { type: 'sine', gain: 0.1, slide: 880, reverb: 0.7 });
        this.noise(1.0, { gain: 0.12, freq: 400, sweep: 6000 });
        break;
      case 'capture':
        [0, 4, 7, 12].forEach((n, i) => this.tone(midi(72 + n) * p, 0.5, { type: 'sine', gain: 0.06, delay: i * 0.09, reverb: 0.5 }));
        this.noise(0.6, { gain: 0.05, freq: 3000, sweep: 2000 });
        break;
      case 'quest':
        [0, 7, 12].forEach((n, i) => this.tone(midi(60 + n) * p, 0.7, { type: 'triangle', gain: 0.07, delay: i * 0.12, reverb: 0.4 }));
        break;
      case 'levelup':
        [0, 4, 7, 12, 16].forEach((n, i) => this.tone(midi(60 + n) * p, 0.6, { type: 'sine', gain: 0.07, delay: i * 0.08, reverb: 0.4 }));
        break;
      case 'chest':
        [0, 5, 9, 12].forEach((n, i) => this.tone(midi(64 + n) * p, 0.5, { type: 'triangle', gain: 0.06, delay: i * 0.07, reverb: 0.3 }));
        break;
      case 'potion':
        this.tone(420 * p, 0.3, { type: 'sine', gain: 0.06, slide: 260 });
        this.tone(620 * p, 0.4, { type: 'sine', gain: 0.04, delay: 0.08, slide: 200 });
        break;
      case 'error':
        this.tone(140 * p, 0.22, { type: 'square', gain: 0.05, slide: -40 });
        break;
      case 'death':
        this.tone(180 * p, 1.2, { type: 'sawtooth', gain: 0.08, slide: -120, filter: 600, reverb: 0.6 });
        break;
      case 'victory':
        [0, 4, 7, 12, 7, 12, 16].forEach((n, i) => this.tone(midi(55 + n) * p, 1.2, { type: 'triangle', gain: 0.07, delay: i * 0.15, reverb: 0.5 }));
        break;
      case 'footstep':
        this.noise(0.08, { gain: 0.025, freq: 220, type: 'lowpass' });
        break;
      case 'seal':
        this.tone(180 * p, 0.8, { type: 'sine', gain: 0.1, slide: 540, reverb: 0.6 });
        break;
      default:
        break;
    }
  }
}

import * as THREE from 'three';
import {
  TAU, mulberry32, toonMaterial, standardMaterial, glowSprite, glowTexture,
  addGlow, box, cyl, sphere, cone, toonGradient,
} from './three-utils.js';
import { buildPlayer, buildSword } from './models.js';
import { APPEARANCE } from './data.js';

function skyDome(top, bottom, sunColor, sunDir, opts = {}) {
  const geo = new THREE.SphereGeometry(opts.radius || 120, 32, 20);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      topColor: { value: new THREE.Color(top) },
      bottomColor: { value: new THREE.Color(bottom) },
      sunColor: { value: new THREE.Color(sunColor) },
      sunDir: { value: new THREE.Vector3(...sunDir).normalize() },
    },
    vertexShader: `
      varying vec3 vWorldPosition;
      void main() {
        vec4 worldPosition = modelMatrix * vec4(position, 1.0);
        vWorldPosition = worldPosition.xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 topColor;
      uniform vec3 bottomColor;
      uniform vec3 sunColor;
      uniform vec3 sunDir;
      varying vec3 vWorldPosition;
      void main() {
        vec3 dir = normalize(vWorldPosition);
        float h = max(0.0, dir.y);
        vec3 col = mix(bottomColor, topColor, pow(h, 0.72));
        float sun = pow(max(dot(dir, normalize(sunDir)), 0.0), 260.0);
        float halo = pow(max(dot(dir, normalize(sunDir)), 0.0), 8.0);
        col += sunColor * sun * 2.0 + sunColor * halo * 0.18;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  return mesh;
}

function mountainSilhouette(scene, x, z, width, height, color) {
  const shape = new THREE.Shape();
  const rng = mulberry32(Math.floor(Math.abs(x * 13 + z * 7)) + 1);
  shape.moveTo(-width / 2, 0);
  const points = 9;
  for (let i = 0; i <= points; i++) {
    const px = -width / 2 + (width * i) / points;
    const py = i === 0 || i === points ? 0 : height * (0.25 + rng() * 0.75);
    shape.lineTo(px, py);
  }
  shape.lineTo(width / 2, 0);
  const geo = new THREE.ShapeGeometry(shape);
  const mat = new THREE.MeshBasicMaterial({ color, fog: false, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, -2, z);
  scene.add(mesh);
  return mesh;
}

function floatingIsland(scene, x, y, z, s, seed = 1) {
  const rng = mulberry32(seed);
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const rockMat = standardMaterial('#3b3a55', { roughness: 0.95 });
  const grassMat = toonMaterial('#5b7b54');
  const top = cyl(3.2 * s, 3.6 * s, 0.8 * s, grassMat, 8);
  top.position.y = 0;
  group.add(top);
  const bottom = new THREE.Mesh(new THREE.ConeGeometry(3.4 * s, 4.2 * s, 8), rockMat);
  bottom.position.y = -2.5 * s;
  bottom.rotation.y = Math.PI / 8;
  group.add(bottom);
  for (let i = 0; i < 7; i++) {
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry((0.3 + rng() * 0.8) * s, 0), rockMat);
    const a = rng() * TAU;
    const r = (1.4 + rng() * 2.2) * s;
    rock.position.set(Math.cos(a) * r, -1.2 * s - rng() * 2.2 * s, Math.sin(a) * r);
    rock.rotation.set(rng() * TAU, rng() * TAU, rng() * TAU);
    group.add(rock);
  }
  for (let i = 0; i < 5; i++) {
    const tree = new THREE.Group();
    const a = rng() * TAU;
    const r = rng() * 2.4 * s;
    tree.position.set(Math.cos(a) * r, 0.4 * s, Math.sin(a) * r);
    const trunk = cyl(0.08 * s, 0.14 * s, 1.4 * s, standardMaterial('#5b4131'), 5);
    trunk.position.y = 0.7 * s;
    tree.add(trunk);
    const canopy = new THREE.Mesh(new THREE.IcosahedronGeometry(0.75 * s, 0), toonMaterial(i % 2 ? '#6f8f5b' : '#7a9c66'));
    canopy.position.y = 1.7 * s;
    tree.add(canopy);
    group.add(tree);
  }
  addGlow(group, '#7ee8fa', 8 * s, [0, -0.6 * s, 0], 0.08);
  scene.add(group);
  return group;
}

export class TitleScene {
  constructor(renderer) {
    this.renderer = renderer;
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2('#0b1830', 0.008);
    this.camera = new THREE.PerspectiveCamera(45, 1, 0.1, 300);
    this.camera.position.set(0, 4.6, 14);
    this.time = 0;
    this.build();
  }

  build() {
    this.scene.add(skyDome('#07152e', '#ef9f6f', '#ffd9a0', [0.25, 0.3, -1], { radius: 160 }));
    const sun = glowSprite('#ffd9a0', 26, 0.55);
    sun.position.set(34, 28, -95);
    this.scene.add(sun);

    // stars
    const rng = mulberry32(31);
    const positions = [];
    for (let i = 0; i < 500; i++) {
      const theta = rng() * TAU;
      const phi = Math.acos(rng() * 0.8);
      const r = 150;
      positions.push(r * Math.sin(phi) * Math.cos(theta), r * Math.cos(phi), r * Math.sin(phi) * Math.sin(theta));
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
      color: '#d8ecff', size: 0.9, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    this.scene.add(this.stars);

    for (let i = 0; i < 5; i++) {
      const z = -65 - i * 16;
      mountainSilhouette(this.scene, -50 + i * 24, z, 80 + i * 20, 18 + i * 8, i % 2 ? '#172a46' : '#102039');
    }

    // ground cliff
    const cliff = new THREE.Mesh(
      new THREE.CylinderGeometry(24, 19, 7, 7),
      standardMaterial('#2b3146', { roughness: 1 }),
    );
    cliff.position.set(0, -5.5, 0);
    this.scene.add(cliff);
    const ground = new THREE.Mesh(new THREE.CircleGeometry(23, 32), toonMaterial('#3e4d4c'));
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.95;
    this.scene.add(ground);

    // ruin arch
    const stone = standardMaterial('#8b8578', { roughness: 0.9 });
    for (const s of [-1, 1]) {
      const col = cyl(0.65, 0.9, 7, stone, 6);
      col.position.set(s * 4.2, 1.5, -1.5);
      col.rotation.z = s * 0.03;
      this.scene.add(col);
      const cap = box(1.7, 0.45, 1.7, stone);
      cap.position.set(s * 4.2, 5.2, -1.5);
      this.scene.add(cap);
    }
    const lintel = box(10, 0.8, 1.4, stone);
    lintel.position.set(0, 5.75, -1.5);
    lintel.rotation.z = 0.02;
    this.scene.add(lintel);

    // sword monument
    const pedestal = new THREE.Group();
    pedestal.position.set(0, -1.7, 0.2);
    const base = cyl(2.1, 2.5, 0.7, stone, 8);
    base.position.y = 0.35;
    pedestal.add(base);
    const block = box(1.4, 1.0, 1.4, stone);
    block.position.y = 1.2;
    block.rotation.y = Math.PI / 4;
    pedestal.add(block);
    this.scene.add(pedestal);

    const sword = buildSword('espada_celestial', 4.2);
    sword.position.set(0, 3.0, 0.2);
    sword.rotation.set(0.12, 0.45, 0.03);
    this.scene.add(sword);
    this.sword = sword;
    addGlow(sword, '#fff0a8', 8, [0, 1.2, 0], 0.45);
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(4.2, 0.035, 4, 64),
      new THREE.MeshBasicMaterial({ color: '#f4d58d', transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending }),
    );
    ring.position.set(0, 2.6, 0.2);
    ring.rotation.x = Math.PI / 2;
    this.scene.add(ring);
    this.ring = ring;

    floatingIsland(this.scene, -12, 7, -18, 1.25, 4);
    floatingIsland(this.scene, 14, 11, -28, 0.85, 9);
    floatingIsland(this.scene, 7, 2.2, -11, 0.45, 12);

    // foreground rocks / grass
    const rng2 = mulberry32(7);
    for (let i = 0; i < 24; i++) {
      const a = rng2() * TAU;
      const r = 9 + rng2() * 12;
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.4 + rng2() * 1.1, 0),
        standardMaterial(rng2() > 0.5 ? '#3c4353' : '#4b4a52'),
      );
      rock.position.set(Math.cos(a) * r, -1.8 + rng2() * 0.4, Math.sin(a) * r);
      rock.rotation.set(rng2() * TAU, rng2() * TAU, rng2() * TAU);
      this.scene.add(rock);
    }

    // lights
    this.scene.add(new THREE.HemisphereLight('#9dc8ff', '#1b1a2c', 1.4));
    const key = new THREE.DirectionalLight('#ffd9a0', 2.6);
    key.position.set(12, 20, 12);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight('#7ee8fa', 1.6);
    rim.position.set(-14, 8, -8);
    this.scene.add(rim);

    // particles
    this.particles = [];
    for (let i = 0; i < 90; i++) {
      const p = glowSprite(i % 3 ? '#ffd58a' : '#7ee8fa', 0.12 + rng2() * 0.28, 0.3 + rng2() * 0.5);
      p.position.set((rng2() - 0.5) * 30, rng2() * 14 - 1, (rng2() - 0.5) * 24);
      p.userData = { baseY: p.position.y, phase: rng2() * TAU, speed: 0.15 + rng2() * 0.4 };
      this.scene.add(p);
      this.particles.push(p);
    }

    this.clouds = [];
    for (let i = 0; i < 8; i++) {
      const c = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture(), color: '#d5c5c0', transparent: true, opacity: 0.06, depthWrite: false,
      }));
      c.scale.set(30 + rng2() * 30, 8 + rng2() * 8, 1);
      c.position.set((rng2() - 0.5) * 120, 18 + rng2() * 18, -50 - rng2() * 50);
      this.scene.add(c);
      this.clouds.push(c);
    }
  }

  update(dt) {
    this.time += dt;
    const t = this.time;
    this.camera.position.x = Math.sin(t * 0.1) * 3.4;
    this.camera.position.y = 4.3 + Math.sin(t * 0.17) * 0.5;
    this.camera.position.z = 13.5 + Math.cos(t * 0.1) * 0.8;
    this.camera.lookAt(0, 2.8, 0);
    this.sword.rotation.y = 0.45 + Math.sin(t * 0.22) * 0.08;
    this.sword.userData.gem.rotation.y += dt * 0.9;
    this.ring.rotation.z += dt * 0.18;
    this.ring.material.opacity = 0.3 + Math.sin(t * 1.3) * 0.1;
    this.stars.rotation.y += dt * 0.004;
    for (const p of this.particles) {
      p.position.y = p.userData.baseY + Math.sin(t * p.userData.speed + p.userData.phase) * 1.8;
      p.material.opacity = 0.25 + Math.sin(t * 2 + p.userData.phase) * 0.2;
    }
    for (const c of this.clouds) c.position.x += dt * 0.2;
  }

  resize(w, h) {
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }
}

export class CharacterPreview {
  constructor(renderer) {
    this.renderer = renderer;
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2('#0b1228', 0.045);
    this.camera = new THREE.PerspectiveCamera(38, 1, 0.1, 60);
    this.camera.position.set(0, 1.6, 4.4);
    this.time = 0;
    this.model = null;
    this.build();
  }

  build() {
    this.scene.add(skyDome('#07152e', '#2a3b5e', '#ffd9a0', [0.2, 0.6, 1], { radius: 40 }));
    this.scene.add(new THREE.HemisphereLight('#b9dcff', '#1a1d2c', 1.3));
    const key = new THREE.DirectionalLight('#ffe2b0', 3.0);
    key.position.set(3, 5, 4);
    key.castShadow = true;
    key.shadow.mapSize.set(512, 512);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight('#7ee8fa', 2.2);
    rim.position.set(-4, 3, -2);
    this.scene.add(rim);

    const platform = new THREE.Group();
    const base = cyl(1.5, 1.8, 0.22, standardMaterial('#3d4256', { metalness: 0.2, roughness: 0.7 }), 32);
    platform.add(base);
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(1.25, 0.025, 4, 64),
      new THREE.MeshBasicMaterial({ color: '#f4d58d', transparent: true, opacity: 0.65, blending: THREE.AdditiveBlending }),
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.14;
    platform.add(ring);
    const inner = new THREE.Mesh(
      new THREE.RingGeometry(0.5, 1.1, 64),
      new THREE.MeshBasicMaterial({ color: '#7ee8fa', transparent: true, opacity: 0.12, side: THREE.DoubleSide, blending: THREE.AdditiveBlending }),
    );
    inner.rotation.x = -Math.PI / 2;
    inner.position.y = 0.16;
    platform.add(inner);
    this.platform = platform;
    this.scene.add(platform);

    this.particles = [];
    const rng = mulberry32(55);
    for (let i = 0; i < 45; i++) {
      const p = glowSprite(i % 2 ? '#ffd58a' : '#7ee8fa', 0.08 + rng() * 0.16, 0.4);
      p.position.set((rng() - 0.5) * 5, 0.3 + rng() * 4, (rng() - 0.5) * 4);
      p.userData = { baseY: p.position.y, phase: rng() * TAU };
      this.scene.add(p);
      this.particles.push(p);
    }
    this.ring = ring;
  }

  setProfile(profile) {
    if (this.model) this.scene.remove(this.model.group);
    const appearance = profile.appearance || {};
    this.model = buildPlayer(appearance, profile.weapon || 'filo_aurora', profile.armor || 'tunica_viajero', profile.headgear || 'ninguno');
    this.model.group.position.y = 0.2;
    this.model.group.rotation.y = Math.PI;
    this.scene.add(this.model.group);
  }

  update(dt) {
    this.time += dt;
    const t = this.time;
    if (this.model) {
      this.model.pose.moving = 0;
      this.model.pose.time += dt;
      this.model.group.rotation.y = Math.PI + Math.sin(t * 0.35) * 0.22;
      this.model.group.position.y = 0.2 + Math.sin(t * 1.2) * 0.01;
    }
    this.platform.rotation.y += dt * 0.08;
    this.ring.rotation.z += dt * 0.15;
    this.camera.position.x = Math.sin(t * 0.12) * 0.35;
    this.camera.lookAt(0, 1.15, 0);
    for (const p of this.particles) {
      p.position.y = p.userData.baseY + Math.sin(t * 0.8 + p.userData.phase) * 0.35;
    }
  }

  resize(w, h) {
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }
}

@font-face {
  font-family: 'Cinzel';
  src: url('/fonts/cinzel.woff2') format('woff2');
  font-weight: 400 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('/fonts/manrope.woff2') format('woff2');
  font-weight: 200 800;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/cormorant.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: url('/fonts/cormorant-italic.woff2') format('woff2');
  font-weight: 300 700;
  font-style: italic;
  font-display: swap;
}

:root {
  --ink: #060b17;
  --ink-2: #0b1427;
  --ink-3: #111d35;
  --panel: rgba(9, 16, 31, 0.84);
  --panel-2: rgba(13, 24, 44, 0.74);
  --line: rgba(244, 213, 141, 0.2);
  --line-strong: rgba(244, 213, 141, 0.48);
  --gold: #f4d58d;
  --gold-2: #d8b25f;
  --gold-3: #a67c36;
  --cyan: #7ee8fa;
  --cyan-2: #3eaec5;
  --rose: #ff8fb1;
  --ember: #ff8a4a;
  --violet: #c6b7ff;
  --text: #f5f0e6;
  --muted: #aeb7c9;
  --muted-2: #78849b;
  --danger: #ff6b6b;
  --ok: #9ef0b4;
  --font-title: 'Cinzel', 'Times New Roman', serif;
  --font-ui: 'Manrope', 'Segoe UI', sans-serif;
  --font-body: 'Cormorant Garamond', Georgia, serif;
  --font-scale: 1;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: var(--font-ui);
  font-size: calc(16px * var(--font-scale));
  overscroll-behavior: none;
  user-select: none;
}

body {
  touch-action: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: 0;
  background: none;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 40%, rgba(26, 53, 91, 0.32), transparent 55%),
    var(--ink);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(2, 5, 12, 0.3) 78%, rgba(2, 4, 9, 0.72) 100%),
    linear-gradient(to bottom, rgba(3, 6, 13, 0.2), transparent 18%, transparent 78%, rgba(3, 6, 13, 0.4));
}

#grain {
  position: absolute;
  inset: -20%;
  z-index: 3;
  opacity: 0.055;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.7'/%3E%3C/svg%3E");
  animation: grainShift 0.6s steps(2) infinite;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.hidden {
  display: none !important;
}

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
}

.overlay {
  position: absolute;
  inset: 0;
  z-index: 50;
}

.eyebrow {
  display: block;
  font-family: var(--font-ui);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

h1,
h2,
h3 {
  font-family: var(--font-title);
  font-weight: 600;
}

.primary-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.7em;
  padding: 0.85em 1.4em;
  border: 1px solid rgba(244, 213, 141, 0.7);
  background: linear-gradient(135deg, rgba(244, 213, 141, 0.2), rgba(244, 213, 141, 0.06));
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transition: background 0.25s var(--ease), transform 0.25s var(--ease), box-shadow 0.25s;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.03);
}
.primary-button:hover {
  background: linear-gradient(135deg, rgba(244, 213, 141, 0.36), rgba(244, 213, 141, 0.1));
  box-shadow: 0 0 26px rgba(244, 213, 141, 0.16), inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  transform: translateY(-1px);
}
.primary-button:active {
  transform: translateY(0);
}
.primary-button span {
  color: var(--gold);
}

.ghost-button {
  padding: 0.7em 1em;
  border: 1px solid rgba(244, 213, 141, 0.18);
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: all 0.25s var(--ease);
}
.ghost-button:hover {
  color: var(--text);
  border-color: var(--line-strong);
  background: rgba(244, 213, 141, 0.06);
}
.ghost-button.danger:hover {
  color: #ffb3b3;
  border-color: rgba(255, 107, 107, 0.5);
  background: rgba(255, 107, 107, 0.07);
}

.icon-button {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(244, 213, 141, 0.18);
  background: rgba(6, 12, 24, 0.55);
  backdrop-filter: blur(10px);
  color: var(--gold);
  transition: all 0.2s var(--ease);
}
.icon-button:hover {
  border-color: var(--line-strong);
  background: rgba(244, 213, 141, 0.08);
}
.icon-button svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.icon-button svg path[d*='h5v16'] {
  fill: currentColor;
}

/* ------------------------------------------------------------------ */
/* Loading                                                             */
/* ------------------------------------------------------------------ */

#loading-screen {
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  background:
    radial-gradient(circle at 50% 45%, rgba(32, 68, 111, 0.5), transparent 55%),
    #060b17;
  transition: opacity 0.8s var(--ease);
}
.loading-rune {
  position: relative;
  width: 84px;
  height: 84px;
  animation: slowSpin 9s linear infinite;
}
.loading-rune span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 10px;
  height: 10px;
  margin: -5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 18px var(--gold);
}
.loading-rune span:nth-child(1) { transform: translate(-50%, -50%) translateY(-34px); }
.loading-rune span:nth-child(2) { transform: translate(-50%, -50%) translateX(34px); }
.loading-rune span:nth-child(3) { transform: translate(-50%, -50%) translateY(34px); }
.loading-rune span:nth-child(4) { transform: translate(-50%, -50%) translateX(-34px); }
.loading-rune::before,
.loading-rune::after {
  content: '';
  position: absolute;
  inset: 13px;
  border: 1px solid rgba(244, 213, 141, 0.3);
  transform: rotate(45deg);
}
.loading-rune::after {
  inset: 26px;
  border-color: rgba(126, 232, 250, 0.5);
  animation: slowSpin 4s linear infinite reverse;
}
.loading-title {
  font-family: var(--font-title);
  font-size: 0.9rem;
  letter-spacing: 0.4em;
  color: var(--gold);
}
.loading-text {
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-style: italic;
  color: var(--muted);
}
@keyframes slowSpin {
  to { transform: rotate(360deg); }
}

/* ------------------------------------------------------------------ */
/* Title                                                               */
/* ------------------------------------------------------------------ */

#title-screen {
  background:
    linear-gradient(90deg, rgba(4, 8, 17, 0.9) 0%, rgba(4, 8, 17, 0.58) 38%, transparent 68%),
    linear-gradient(0deg, rgba(4, 8, 17, 0.65), transparent 30%);
}
.title-top {
  position: absolute;
  top: calc(24px + var(--safe-top));
  left: calc(5vw + var(--safe-left));
  right: calc(5vw + var(--safe-right));
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
}
.title-top .version {
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  color: rgba(244, 213, 141, 0.52);
}
.title-logo {
  position: absolute;
  left: calc(7vw + var(--safe-left));
  top: 19%;
  width: min(48vw, 690px);
  animation: titleReveal 1.6s var(--ease) both;
}
@keyframes titleReveal {
  from { opacity: 0; transform: translateY(24px); filter: blur(8px); }
  to { opacity: 1; transform: translateY(0); filter: blur(0); }
}
.logo-ornament {
  display: flex;
  align-items: center;
  gap: 14px;
  width: min(30vw, 380px);
  margin-bottom: 18px;
  opacity: 0.85;
}
.logo-ornament span {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold-2));
}
.logo-ornament span:last-child {
  background: linear-gradient(90deg, var(--gold-2), transparent);
}
.logo-ornament i {
  width: 9px;
  height: 9px;
  border: 1px solid var(--gold);
  transform: rotate(45deg);
  box-shadow: 0 0 12px rgba(244, 213, 141, 0.6);
}
.title-logo h1 {
  display: flex;
  flex-direction: column;
  line-height: 0.88;
  text-shadow: 0 8px 50px rgba(0, 0, 0, 0.65);
}
.title-logo h1 span {
  font-size: clamp(2rem, 4.3vw, 4.8rem);
  font-weight: 400;
  letter-spacing: 0.18em;
  color: #f5f0e6;
}
.title-logo h1 strong {
  font-size: clamp(3.1rem, 7.4vw, 8.2rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 0.9;
  background: linear-gradient(180deg, #fff6d9 0%, #f4d58d 42%, #b9873f 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 26px rgba(244, 213, 141, 0.22));
}
.title-sub {
  margin-top: 18px;
  font-family: var(--font-body);
  font-size: clamp(1rem, 1.5vw, 1.45rem);
  font-style: italic;
  letter-spacing: 0.04em;
  color: rgba(245, 240, 230, 0.7);
}
.title-menu {
  position: absolute;
  left: calc(7vw + var(--safe-left));
  top: 58%;
  width: min(31vw, 390px);
  display: flex;
  flex-direction: column;
  gap: 8px;
  animation: titleReveal 1.6s 0.2s var(--ease) both;
}
.menu-button {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 13px 16px;
  text-align: left;
  border-left: 1px solid rgba(244, 213, 141, 0.2);
  background: linear-gradient(90deg, rgba(244, 213, 141, 0.045), transparent);
  transition: all 0.3s var(--ease);
  position: relative;
}
.menu-button::after {
  content: '';
  position: absolute;
  left: -1px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--gold);
  transform: scaleY(0);
  transition: transform 0.3s var(--ease);
}
.menu-button:hover::after,
.menu-button.primary::after {
  transform: scaleY(1);
}
.menu-button:hover {
  background: linear-gradient(90deg, rgba(244, 213, 141, 0.11), transparent);
  padding-left: 23px;
}
.menu-button.primary {
  border-left-color: var(--gold);
  background: linear-gradient(90deg, rgba(244, 213, 141, 0.1), transparent);
}
.menu-button:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}
.menu-button:disabled:hover {
  padding-left: 16px;
  background: linear-gradient(90deg, rgba(244, 213, 141, 0.045), transparent);
}
.menu-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: var(--gold);
  font-size: 1.1rem;
  border: 1px solid rgba(244, 213, 141, 0.18);
  transform: rotate(45deg);
}
.menu-icon > * {
