  flex-direction: column;
  gap: 2px;
}
.menu-button b {
  font-size: 0.86rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.menu-button small {
  font-size: 0.66rem;
  color: var(--muted);
  letter-spacing: 0.03em;
}
.title-footer {
  position: absolute;
  left: calc(5vw + var(--safe-left));
