  bottom: calc(22px + var(--safe-bottom));
  display: flex;
  justify-content: space-between;
  font-size: 0.58rem;
  letter-spacing: 0.2em;
  color: rgba(174, 183, 201, 0.6);
}
.title-hint {
  color: rgba(244, 213, 141, 0.55);
}

/* ------------------------------------------------------------------ */
/* Character creation                                                  */
/* ------------------------------------------------------------------ */

#creation-screen {
  background:
    linear-gradient(90deg, rgba(5, 9, 19, 0.97) 0%, rgba(5, 9, 19, 0.9) 40%, rgba(5, 9, 19, 0.16) 68%, rgba(5, 9, 19, 0.5) 100%),
    radial-gradient(circle at 70% 50%, transparent, rgba(5, 9, 19, 0.55));
}
.creation-head {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: calc(4vw + var(--safe-left));
  right: calc(4vw + var(--safe-right));
