}
.origin-card.active {
  border-color: var(--gold);
  background: linear-gradient(135deg, rgba(244, 213, 141, 0.11), rgba(244, 213, 141, 0.02));
  box-shadow: inset 0 0 0 1px rgba(244, 213, 141, 0.12);
}
.origin-card b {
  display: block;
  font-family: var(--font-title);
  font-size: 0.78rem;
  color: var(--text);
  margin-bottom: 3px;
}
.origin-card small {
  display: block;
  font-size: 0.58rem;
  line-height: 1.4;
  color: var(--muted);
}
.appearance-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 8px;
  flex-wrap: wrap;
}
.appearance-tab {
  padding: 6px 10px;
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  border-bottom: 1px solid transparent;
}
.appearance-tab.active {
  color: var(--gold);
  border-bottom-color: var(--gold);
}
.swatch-row {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
  min-height: 34px;
  align-items: center;
}
.swatch {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 2px solid transparent;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.12);
  transition: all 0.2s var(--ease);
}
.swatch:hover {
  transform: scale(1.12);
}
.swatch.active {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px rgba(6, 11, 23, 0.9), 0 0 16px rgba(244, 213, 141, 0.4);
}
.swatch-text {
  padding: 7px 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.6rem;
  letter-spacing: 0.06em;
  color: var(--muted);
}
.swatch-text.active {
  border-color: var(--gold);
  color: var(--gold);
  background: rgba(244, 213, 141, 0.06);
}
.weapon-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}
.weapon-card {
  padding: 9px 10px;
  text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.02);
  transition: all 0.2s var(--ease);
}
.weapon-card:hover {
  border-color: rgba(244, 213, 141, 0.28);
}
.weapon-card.active {
  border-color: var(--gold);
  background: rgba(244, 213, 141, 0.07);
}
.weapon-card b {
  display: block;
  font-size: 0.64rem;
  color: var(--text);
}
.weapon-card small {
  display: block;
  margin-top: 2px;
  font-size: 0.54rem;
  color: var(--muted-2);
}
.weapon-card .wstat {
  margin-top: 5px;
  font-size: 0.53rem;
  color: var(--gold);
  letter-spacing: 0.06em;
}
.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 18px;
}
.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.045);
}
.stat-row .stat-name {
  flex: 1;
  font-size: 0.62rem;
  color: var(--muted);
  letter-spacing: 0.04em;
}
.stat-row .stat-value {
  width: 24px;
  text-align: center;
  font-family: var(--font-title);
  font-size: 0.9rem;
  color: var(--text);
}
.stat-row button {
  width: 23px;
  height: 23px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(244, 213, 141, 0.2);
  color: var(--gold);
  font-size: 0.85rem;
  line-height: 1;
}
.stat-row button:hover {
  background: rgba(244, 213, 141, 0.1);
}
.stat-row button:disabled {
  opacity: 0.2;
  cursor: default;
}
.creation-actions {
  margin-top: 18px;
}
.creation-actions .primary-button {
  width: 100%;
  padding: 15px 20px;
}

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */

#hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
}
#hud button,
#hud input {
  pointer-events: auto;
}
#hud-top-left {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: calc(20px + var(--safe-left));
  width: min(330px, 31vw);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.region-badge {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  width: max-content;
  background: linear-gradient(90deg, rgba(6, 12, 24, 0.8), rgba(6, 12, 24, 0.18));
  border-left: 1px solid var(--gold);
  backdrop-filter: blur(8px);
}
.region-rune {
  color: var(--gold);
  font-size: 0.9rem;
}
.region-badge b {
  display: block;
  font-family: var(--font-title);
  font-size: 0.72rem;
  letter-spacing: 0.22em;
}
.region-badge small {
  display: block;
  font-size: 0.52rem;
  color: var(--muted);
  letter-spacing: 0.05em;
  margin-top: 1px;
}
.quest-card {
  position: relative;
  padding: 11px 13px 12px;
  background: linear-gradient(135deg, rgba(7, 14, 28, 0.82), rgba(7, 14, 28, 0.42));
  border: 1px solid rgba(244, 213, 141, 0.14);
  border-left: 2px solid var(--gold);
  backdrop-filter: blur(10px);
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.18);
}
.quest-card::before {
  content: '';
  position: absolute;
  right: 8px;
  top: 8px;
  width: 5px;
  height: 5px;
  border: 1px solid var(--gold);
  transform: rotate(45deg);
  opacity: 0.5;
}
.quest-kicker {
  display: flex;
  justify-content: space-between;
  font-size: 0.5rem;
  letter-spacing: 0.18em;
  color: var(--gold);
  text-transform: uppercase;
}
.quest-kicker #quest-step {
  color: var(--muted-2);
}
.quest-title {
  margin-top: 5px;
  font-family: var(--font-title);
  font-size: 0.84rem;
  color: #fff7e6;
}
.quest-objective {
  margin-top: 4px;
  font-size: 0.62rem;
  line-height: 1.45;
  color: var(--muted);
}
.quest-progress {
  margin-top: 8px;
  height: 3px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.quest-progress span {
  display: block;
  height: 100%;
  width: 0;
  background: linear-gradient(90deg, var(--gold-3), var(--gold));
  transition: width 0.4s var(--ease);
}
#hud-top-right {
  position: absolute;
  top: calc(18px + var(--safe-top));
  right: calc(20px + var(--safe-right));
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.minimap-wrap {
  position: relative;
  width: clamp(112px, 10vw, 146px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid rgba(244, 213, 141, 0.35);
  padding: 4px;
  background: rgba(4, 9, 18, 0.65);
  backdrop-filter: blur(8px);
  box-shadow: 0 0 0 4px rgba(4, 9, 18, 0.3), 0 10px 30px rgba(0, 0, 0, 0.3);
}
#minimap {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
}
.minimap-compass {
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-title);
  font-size: 0.5rem;
  color: var(--gold);
  background: var(--ink);
  padding: 0 5px;
}
.hud-menu-buttons {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.hud-menu-buttons .icon-button {
  width: 36px;
  height: 36px;
  background: rgba(4, 9, 18, 0.55);
}
#hud-bottom-left {
  position: absolute;
  left: calc(20px + var(--safe-left));
  bottom: calc(18px + var(--safe-bottom));
  width: min(330px, 33vw);
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.player-plate {
  display: flex;
  gap: 10px;
  padding: 9px 12px;
  background: linear-gradient(90deg, rgba(6, 12, 24, 0.86), rgba(6, 12, 24, 0.45));
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-left: 2px solid var(--gold);
  backdrop-filter: blur(10px);
}
.player-avatar {
  width: 42px;
  height: 42px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(244, 213, 141, 0.4);
  background: radial-gradient(circle at 40% 30%, #375b7a, #12233b);
  font-family: var(--font-title);
  font-size: 1.1rem;
  color: var(--gold);
  overflow: hidden;
}
.player-avatar svg {
  width: 100%;
  height: 100%;
}
.player-info {
  flex: 1;
  min-width: 0;
}
.player-name-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 4px;
}
.player-name-row b {
  font-family: var(--font-title);
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.player-level {
  font-size: 0.54rem;
  color: var(--gold);
  letter-spacing: 0.06em;
}
.bar {
  position: relative;
  height: 9px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.bar-fill {
  display: block;
  height: 100%;
  width: 100%;
  transition: width 0.18s linear;
}
.hp-bar {
  height: 12px;
  margin-bottom: 4px;
}
.hp-bar .bar-fill {
  background: linear-gradient(90deg, #8a2f3f, #e56473 55%, #ff9a9f);
  box-shadow: 0 0 10px rgba(229, 100, 115, 0.35);
}
.bar-text {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 0.46rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.85);
  text-shadow: 0 1px 3px #000;
}
.bar-row {
  display: flex;
  gap: 4px;
}
.mp-bar,
.sp-bar {
  flex: 1;
  height: 6px;
}
.mp-bar .bar-fill {
  background: linear-gradient(90deg, #3d6e9e, #7ee8fa);
}
.sp-bar .bar-fill {
  background: linear-gradient(90deg, #6e6a33, #e8d97e);
}
.bar-label {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 0.4rem;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.65);
}
.xp-bar {
  height: 2px;
  margin-top: 5px;
  background: rgba(255, 255, 255, 0.06);
}
.xp-bar span {
  display: block;
  width: 0;
  height: 100%;
  background: var(--gold);
  transition: width 0.3s;
}
.companion-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: rgba(6, 12, 24, 0.58);
  border: 1px solid rgba(255, 255, 255, 0.055);
  backdrop-filter: blur(8px);
  opacity: 0.8;
}
.companion-icon {
  color: var(--cyan);
  font-size: 0.8rem;
}
.companion-chip b {
  display: block;
  font-size: 0.55rem;
  letter-spacing: 0.06em;
}
.companion-chip small {
  display: block;
  font-size: 0.48rem;
  color: var(--muted-2);
  margin-top: 1px;
}
#joystick {
  position: absolute;
  left: calc(26px + var(--safe-left));
  bottom: calc(26px + var(--safe-bottom));
  width: 146px;
  height: 146px;
  pointer-events: auto;
  touch-action: none;
}
.joystick-base {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.01) 65%, transparent 70%);
  border: 1px solid rgba(244, 213, 141, 0.14);
  backdrop-filter: blur(2px);
}
.joystick-ring {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  border: 1px dashed rgba(244, 213, 141, 0.12);
}
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 54px;
  height: 54px;
  margin: -27px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, rgba(244, 213, 141, 0.35), rgba(244, 213, 141, 0.1));
  border: 1px solid rgba(244, 213, 141, 0.45);
  box-shadow: 0 0 22px rgba(244, 213, 141, 0.15);
  transition: transform 0.06s linear;
}
.joystick-label {
  position: absolute;
  bottom: -17px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.44rem;
  letter-spacing: 0.18em;
  color: rgba(244, 213, 141, 0.4);
}
#actions {
  position: absolute;
  right: calc(24px + var(--safe-right));
  bottom: calc(20px + var(--safe-bottom));
  pointer-events: auto;
}
.action-cluster {
  display: grid;
  grid-template-columns: repeat(4, auto);
  grid-template-rows: repeat(2, auto);
  gap: 8px;
  align-items: end;
  justify-items: end;
}
.action-button {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: 1px solid rgba(244, 213, 141, 0.24);
  background: radial-gradient(circle at 38% 30%, rgba(35, 53, 82, 0.9), rgba(6, 12, 24, 0.86));
  color: var(--text);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25), inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(8px);
  transition: transform 0.1s, border-color 0.2s, background 0.2s;
  touch-action: none;
}
.action-button:hover {
  border-color: rgba(244, 213, 141, 0.6);
}
.action-button:active,
.action-button.pressed {
  transform: scale(0.92);
  background: radial-gradient(circle at 38% 30%, rgba(244, 213, 141, 0.26), rgba(6, 12, 24, 0.9));
}
.action-button svg {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.action-button.attack {
  grid-column: 4;
  grid-row: 2;
  width: 84px;
  height: 84px;
  border-color: rgba(244, 213, 141, 0.55);
  background: radial-gradient(circle at 38% 30%, rgba(244, 213, 141, 0.28), rgba(31, 27, 25, 0.94));
  box-shadow: 0 0 30px rgba(244, 213, 141, 0.14), inset 0 0 0 1px rgba(244, 213, 141, 0.15);
}
.action-button.attack svg {
  width: 34px;
  height: 34px;
}
.action-button.heavy {
  grid-column: 3;
  grid-row: 2;
  width: 64px;
  height: 64px;
  color: #ffd0b3;
}
.action-button.utility {
  width: 52px;
  height: 52px;
}
.action-button.utility svg {
  width: 21px;
  height: 21px;
}
.action-button.dodge { grid-column: 4; grid-row: 1; }
.action-button.spell { grid-column: 3; grid-row: 1; color: var(--cyan); }
.action-button.creature { grid-column: 2; grid-row: 1; color: var(--violet); }
.action-button.block { grid-column: 2; grid-row: 2; }
.action-button.potion {
  grid-column: 1;
  grid-row: 2;
  width: 44px;
  height: 44px;
  color: #ffb0a0;
}
.action-button.ultimate {
  grid-column: 1;
  grid-row: 1;
  color: var(--gold);
  border-color: rgba(244, 213, 141, 0.55);
  animation: ultimatePulse 2.4s ease-in-out infinite;
}
@keyframes ultimatePulse {
  0%, 100% { box-shadow: 0 0 12px rgba(244, 213, 141, 0.12); }
  50% { box-shadow: 0 0 28px rgba(244, 213, 141, 0.35); }
}
.key-hint {
  position: absolute;
  right: -3px;
  bottom: -2px;
  display: grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 3px;
  border-radius: 3px;
  background: rgba(4, 8, 16, 0.9);
  border: 1px solid rgba(244, 213, 141, 0.18);
  font-size: 0.42rem;
  font-weight: 700;
  color: var(--muted);
}
.action-button.attack .key-hint {
  width: 20px;
  height: 20px;
  font-size: 0.5rem;
}
.cooldown-ring {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(rgba(126, 232, 250, 0.6) 0deg, transparent 0deg);
  mask: radial-gradient(circle, transparent 63%, #000 65%);
  -webkit-mask: radial-gradient(circle, transparent 63%, #000 65%);
  pointer-events: none;
}
.potion-count {
  position: absolute;
  top: -3px;
  left: -3px;
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--gold);
  color: #241a0e;
  font-size: 0.46rem;
  font-weight: 800;
}
#interaction-prompt {
  position: absolute;
  left: 50%;
  bottom: calc(130px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px 8px 8px;
  background: rgba(5, 11, 22, 0.82);
  border: 1px solid rgba(244, 213, 141, 0.35);
  backdrop-filter: blur(12px);
  font-size: 0.68rem;
  letter-spacing: 0.04em;
  animation: promptIn 0.25s var(--ease);
  pointer-events: auto;
  cursor: pointer;
}
@keyframes promptIn {
  from { opacity: 0; transform: translate(-50%, 8px); }
}
.interact-key {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--gold);
  color: var(--gold);
  font-size: 0.7rem;
  font-weight: 800;
}
#boss-bar {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  width: min(520px, 46vw);
  text-align: center;
  animation: bossIn 0.6s var(--ease);
}
@keyframes bossIn {
  from { opacity: 0; transform: translate(-50%, -10px); }
}
.boss-name {
  font-family: var(--font-title);
  font-size: 0.72rem;
  letter-spacing: 0.24em;
  color: #ffe7c1;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.7);
}
.boss-bar-track {
  position: relative;
  height: 7px;
  margin-top: 5px;
  background: rgba(4, 8, 16, 0.7);
  border: 1px solid rgba(244, 213, 141, 0.28);
  overflow: hidden;
}
.boss-bar-track span {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #7a1e2c, #e14b4b 55%, #ff9a7a);
  transition: width 0.25s linear;
}
.boss-phase {
  margin-top: 3px;
  font-size: 0.44rem;
  letter-spacing: 0.22em;
  color: rgba(244, 213, 141, 0.55);
}
#combo-display {
  position: absolute;
  right: calc(26px + var(--safe-right));
  top: 43%;
  text-align: right;
  animation: comboIn 0.2s var(--ease);
}
#combo-display b {
  display: block;
  font-family: var(--font-title);
  font-size: 2.2rem;
  line-height: 0.9;
  color: var(--gold);
  text-shadow: 0 0 20px rgba(244, 213, 141, 0.4);
}
#combo-display span {
  font-size: 0.46rem;
  letter-spacing: 0.24em;
  color: var(--muted);
}
@keyframes comboIn {
  from { opacity: 0; transform: translateX(8px); }
}
#damage-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.damage-number {
  position: absolute;
  font-family: var(--font-title);
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff0d0;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.85);
  animation: damageFloat 0.9s var(--ease) forwards;
  white-space: nowrap;
}
.damage-number.crit {
  font-size: 1.65rem;
  color: #ffd166;
}
.damage-number.heal {
  color: #9ef0b4;
}
.damage-number.player {
  color: #ff9a9f;
}
@keyframes damageFloat {
  0% { opacity: 0; transform: translate(-50%, 8px) scale(0.8); }
  15% { opacity: 1; transform: translate(-50%, 0) scale(1.08); }
  100% { opacity: 0; transform: translate(-50%, -46px) scale(1); }
}
#toast-layer {
  position: absolute;
  top: calc(20px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  z-index: 60;
  width: min(430px, 70vw);
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
  background: rgba(6, 13, 26, 0.9);
  border: 1px solid rgba(244, 213, 141, 0.24);
  border-left: 2px solid var(--gold);
  backdrop-filter: blur(12px);
  animation: toastIn 0.35s var(--ease), toastOut 0.4s 3.2s var(--ease) forwards;
  max-width: 100%;
}
.toast .toast-icon {
  color: var(--gold);
  font-size: 0.9rem;
}
.toast .toast-text b {
  display: block;
  font-size: 0.68rem;
  letter-spacing: 0.06em;
}
.toast .toast-text small {
  display: block;
  font-size: 0.56rem;
  color: var(--muted);
  margin-top: 1px;
}
.toast.capture { border-left-color: var(--cyan); }
.toast.capture .toast-icon { color: var(--cyan); }
.toast.level { border-left-color: var(--violet); }
.toast.level .toast-icon { color: var(--violet); }
@keyframes toastIn {
  from { opacity: 0; transform: translateY(-12px); }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-10px); }
}
.hud-hint {
  position: absolute;
  left: 50%;
  bottom: calc(14px + var(--safe-bottom));
  transform: translateX(-50%);
  font-size: 0.5rem;
  letter-spacing: 0.08em;
  color: rgba(174, 183, 201, 0.5);
  white-space: nowrap;
}

/* ------------------------------------------------------------------ */
/* Dialogue and cinematics                                             */
/* ------------------------------------------------------------------ */

#dialogue-overlay {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 5vw calc(5vh + var(--safe-bottom));
  background: linear-gradient(0deg, rgba(3, 7, 15, 0.78), transparent 55%);
}
.dialogue-box {
  width: min(900px, 90vw);
  display: flex;
  gap: 18px;
  padding: 18px;
  background: linear-gradient(135deg, rgba(8, 15, 30, 0.96), rgba(11, 20, 38, 0.88));
  border: 1px solid rgba(244, 213, 141, 0.28);
  border-top: 2px solid var(--gold);
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(16px);
  animation: dialogueIn 0.35s var(--ease);
}
@keyframes dialogueIn {
  from { opacity: 0; transform: translateY(18px); }
}
.portrait-frame {
  flex: none;
  width: 126px;
  height: 154px;
  border: 1px solid rgba(244, 213, 141, 0.25);
  background: radial-gradient(circle at 50% 30%, rgba(126, 232, 250, 0.1), rgba(4, 8, 18, 0.9));
  overflow: hidden;
}
.portrait-frame svg {
  width: 100%;
  height: 100%;
