}
.dialogue-choice b {
  color: var(--gold);
  margin-right: 6px;
}
.dialogue-continue {
  margin-top: 12px;
  font-size: 0.52rem;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}
.dialogue-continue b {
  color: var(--gold);
}
.dialogue-continue span {
  display: inline-block;
  animation: bob 1s infinite;
  color: var(--gold);
}
@keyframes bob {
  50% { transform: translateY(3px); }
}

#cinematic-overlay {
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 50%, rgba(12, 22, 40, 0.35), rgba(2, 5, 12, 0.88));
  backdrop-filter: blur(3px);
}
.cinematic-bars {
  position: absolute;
  left: 0;
  right: 0;
  height: 8vh;
  background: #02050b;
  z-index: 2;
}
.cinematic-bars.top { top: 0; }
.cinematic-bars.bottom { bottom: 0; }
.cinematic-content {
  width: min(760px, 84vw);
  text-align: center;
  z-index: 3;
}
.cinematic-kicker {
  font-size: 0.58rem;
  letter-spacing: 0.34em;
  color: var(--gold);
