}
.pause-content {
  flex: 1;
  overflow-y: auto;
  padding: 22px 26px;
  scrollbar-width: thin;
  scrollbar-color: var(--gold-3) transparent;
}
.pause-content::-webkit-scrollbar {
  width: 4px;
}
