  text-transform: uppercase;
  color: var(--gold);
}
.equip-card b {
  display: block;
  margin-top: 4px;
  font-family: var(--font-title);
  font-size: 0.72rem;
}
.equip-card p {
  margin-top: 5px;
  font-size: 0.56rem;
  line-height: 1.45;
