  margin-top: 2px;
  font-size: 0.53rem;
  color: var(--muted-2);
}
.setting-row input[type='range'] {
  width: 150px;
  accent-color: var(--gold);
}
.setting-row select {
  padding: 6px 10px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(244, 213, 141, 0.2);
  color: var(--text);
  font-size: 0.6rem;
}
.toggle {
  position: relative;
  width: 38px;
  height: 21px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.2s;
  flex: none;
}
.toggle::after {
  content: '';
  position: absolute;
  left: 2px;
  top: 2px;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: var(--muted);
  transition: all 0.2s var(--ease);
}
.toggle.on {
  background: rgba(244, 213, 141, 0.22);
  border-color: rgba(244, 213, 141, 0.4);
}
.toggle.on::after {
  left: 19px;
  background: var(--gold);
