  background: linear-gradient(145deg, rgba(9, 17, 33, 0.98), rgba(6, 12, 24, 0.98));
  border: 1px solid rgba(126, 232, 250, 0.3);
  border-top: 2px solid var(--cyan);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
  animation: dialogueIn 0.3s var(--ease);
}
.capture-portrait {
  flex: none;
  width: 170px;
  height: 200px;
  background: radial-gradient(circle at 50% 40%, rgba(126, 232, 250, 0.15), rgba(4, 8, 18, 0.9));
  border: 1px solid rgba(126, 232, 250, 0.2);
  overflow: hidden;
}
.capture-portrait svg {
  width: 100%;
  height: 100%;
}
.capture-info {
  flex: 1;
}
.capture-info h3 {
  margin-top: 5px;
  font-size: 1.4rem;
}
.capture-title {
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  color: var(--cyan);
  text-transform: uppercase;
}
.capture-info > p:not(.capture-title) {
  margin-top: 9px;
  font-family: var(--font-body);
  font-size: 0.92rem;
  line-height: 1.45;
  color: var(--muted);
}
.capture-chance,
.capture-cost {
  display: flex;
  justify-content: space-between;
  margin-top: 10px;
  padding-top: 7px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 0.6rem;
  color: var(--muted);
}
.capture-chance b {
  color: var(--cyan);
}
.capture-cost b {
  color: var(--gold);
}
.capture-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.capture-actions button {
  flex: 1;
}

/* ------------------------------------------------------------------ */
/* Death / Ending                                                      */
/* ------------------------------------------------------------------ */

#death-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 45%, rgba(90, 18, 28, 0.35), rgba(2, 5, 12, 0.94));
  backdrop-filter: blur(5px);
}
.death-content {
  text-align: center;
  max-width: 540px;
}
.death-rune {
  display: block;
  font-size: 2rem;
  color: #ff7a7a;
  opacity: 0.7;
  animation: pulse 2.4s infinite;
}
@keyframes pulse {
  50% { opacity: 0.3; transform: scale(0.94); }
}
.death-content h2 {
  margin-top: 10px;
  font-size: clamp(2.2rem, 5vw, 4rem);
  color: #ffe7e7;
}
.death-content p {
  margin-top: 10px;
  font-family: var(--font-body);
  font-size: 1.15rem;
  font-style: italic;
  color: var(--muted);
}
.death-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 24px;
  align-items: center;
}
#ending-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 50% 30%, rgba(126, 232, 250, 0.1), transparent 45%),
    radial-gradient(circle at 50% 50%, rgba(10, 20, 40, 0.7), rgba(2, 5, 12, 0.96));
  overflow-y: auto;
  padding: 30px;
}
.ending-content {
  width: min(780px, 92vw);
  text-align: center;
  animation: titleReveal 1.2s var(--ease);
}
.ending-content h2 {
  margin-top: 12px;
  font-size: clamp(2rem, 4.8vw, 4rem);
  letter-spacing: 0.06em;
  color: #fff2d0;
  text-shadow: 0 0 50px rgba(244, 213, 141, 0.2);
}
.ending-subtitle {
  margin-top: 5px;
  font-family: var(--font-body);
  font-size: 1.3rem;
  font-style: italic;
  color: var(--gold);
}
.ending-text {
  margin-top: 22px;
  font-family: var(--font-body);
  font-size: clamp(1rem, 1.3vw, 1.15rem);
  line-height: 1.65;
  color: rgba(245, 240, 230, 0.82);
  text-align: left;
}
.ending-epilogue {
  margin-top: 18px;
  padding: 14px 18px;
  border-left: 2px solid var(--gold);
  background: rgba(244, 213, 141, 0.04);
  font-family: var(--font-body);
  font-size: 1rem;
  font-style: italic;
  text-align: left;
  color: var(--gold);
}
.ending-stats {
  display: flex;
  justify-content: center;
  gap: 26px;
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid rgba(244, 213, 141, 0.15);
}
.ending-stat span {
  display: block;
  font-size: 0.48rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted-2);
}
.ending-stat b {
  display: block;
  margin-top: 3px;
  font-family: var(--font-title);
  font-size: 1rem;
  color: var(--gold);
}
.ending-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

/* ------------------------------------------------------------------ */
/* Modals                                                              */
/* ------------------------------------------------------------------ */

.modal {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(2, 6, 14, 0.78);
  backdrop-filter: blur(12px);
}
.modal-card {
  width: min(780px, 94vw);
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(145deg, rgba(9, 17, 33, 0.99), rgba(5, 10, 21, 0.99));
  border: 1px solid rgba(244, 213, 141, 0.22);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
  animation: dialogueIn 0.3s var(--ease);
}
.modal-card header {
  position: relative;
  padding: 20px 24px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.modal-card header h3 {
  margin-top: 4px;
  font-size: 1.2rem;
}
.modal-card header .modal-close {
  position: absolute;
  right: 16px;
  top: 16px;
}
.modal-card footer {
  padding: 14px 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  justify-content: flex-end;
}
.settings-grid {
  padding: 16px 24px;
  overflow-y: auto;
}
.credits-body {
  padding: 22px 24px;
  overflow-y: auto;
}
.credits-lead {
  font-family: var(--font-body);
  font-size: 1.15rem;
  line-height: 1.5;
  font-style: italic;
  color: var(--muted);
}
.credits-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  margin-top: 18px;
}
.credits-columns h4 {
  font-size: 0.52rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold);
  margin-top: 12px;
}
.credits-columns h4:first-child {
  margin-top: 0;
}
.credits-columns p {
  margin-top: 2px;
  font-size: 0.62rem;
  color: var(--muted);
}
.credits-note {
  margin-top: 20px;
  padding-top: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 0.54rem;
  line-height: 1.55;
  color: var(--muted-2);
}

#rotate-screen {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 300;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: #060b17;
  text-align: center;
  padding: 30px;
}
.rotate-icon {
  font-size: 2.4rem;
  color: var(--gold);
  animation: slowSpin 4s linear infinite;
}
#rotate-screen h3 {
  font-size: 1.3rem;
}
#rotate-screen p {
  font-size: 0.65rem;
  color: var(--muted);
}
#offline-indicator {
  position: fixed;
  left: 50%;
  bottom: 10px;
  transform: translateX(-50%);
  z-index: 110;
  padding: 5px 10px;
  background: rgba(255, 138, 74, 0.15);
  border: 1px solid rgba(255, 138, 74, 0.4);
  font-size: 0.5rem;
  color: var(--ember);
}

/* ------------------------------------------------------------------ */
/* Utility states                                                      */
/* ------------------------------------------------------------------ */

body.high-contrast {
  --panel: rgba(0, 0, 0, 0.94);
  --muted: #d7dbe4;
  --muted-2: #aeb4c4;
  --line: rgba(255, 230, 160, 0.45);
}
body.high-contrast .quest-card,
body.high-contrast .player-plate,
body.high-contrast .dialogue-box,
body.high-contrast .pause-shell,
body.high-contrast .map-shell {
  border-color: rgba(255, 230, 160, 0.55);
}
body.reduce-motion *,
body.reduce-motion *::before,
body.reduce-motion *::after {
  animation-duration: 0.001ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.001ms !important;
}

@media (pointer: coarse) {
  .hud-hint { display: none; }
  #hud-bottom-left {
    top: calc(124px + var(--safe-top));
    bottom: auto;
    width: min(300px, 36vw);
  }
  #joystick { display: block; }
  .key-hint { display: none; }
  .action-button { width: 58px; height: 58px; }
  .action-button.attack { width: 86px; height: 86px; }
  .action-button.heavy { width: 66px; height: 66px; }
  .action-button.utility { width: 54px; height: 54px; }
  .action-button.potion { width: 46px; height: 46px; }
  #interaction-prompt { bottom: calc(120px + var(--safe-bottom)); }
}
@media (pointer: fine) {
  #joystick { display: none; }
}

@media (max-width: 900px) {
  #hud-top-left { width: 37vw; }
  #hud-bottom-left { width: 38vw; }
  .title-logo { width: 56vw; }
  .title-menu { width: 40vw; }
  .creation-panel { width: 52vw; }
  .preview-name { font-size: 2rem; }
  .dialogue-box { padding: 14px; gap: 13px; }
  .portrait-frame { width: 100px; height: 126px; }
  .map-sidebar { width: 250px; }
}

@media (max-height: 560px) {
  .title-logo { top: 14%; }
  .title-logo h1 span { font-size: clamp(1.6rem, 3.4vw, 3rem); }
  .title-logo h1 strong { font-size: clamp(2.5rem, 6vw, 5rem); }
  .title-sub { margin-top: 10px; font-size: 0.9rem; }
  .title-menu { top: 52%; }
  .menu-button { padding: 8px 12px; }
  .menu-button small { display: none; }
  .menu-icon { width: 26px; height: 26px; font-size: 0.8rem; }
  .creation-head { top: calc(10px + var(--safe-top)); }
  .creation-head h2 { font-size: 1rem; }
  .creation-body { inset: calc(62px + var(--safe-top)) 3vw calc(10px + var(--safe-bottom)) 3vw; }
  .field-group { margin-bottom: 11px; }
  .origin-card { padding: 7px 9px; }
  .origin-card small { display: none; }
  .stat-row { padding: 2px 0; }
  .creation-actions { margin-top: 10px; }
  .creation-actions .primary-button { padding: 10px 14px; }
  .preview-stats { bottom: 2%; }
  .preview-hint { display: none; }
  .pause-shell { height: 96vh; }
  .pause-head { padding: 12px 18px; }
  .pause-tabs button { padding: 9px 12px; }
  .pause-content { padding: 14px 18px; }
  .pause-footer { padding: 8px 16px; }
  .dialogue-text { min-height: 50px; font-size: 0.96rem; }
  .dialogue-box { width: 94vw; padding: 12px; }
  .portrait-frame { width: 88px; height: 112px; }
  .dialogue-speaker { margin-bottom: 4px; }
  .dialogue-continue { margin-top: 6px; }
  .capture-card { padding: 14px; gap: 14px; }
  .capture-portrait { width: 130px; height: 158px; }
  .capture-info > p:not(.capture-title) { font-size: 0.8rem; margin-top: 5px; }
  .map-head { padding: 10px 16px; }
  .map-head h2 { font-size: 1rem; }
  .map-body { flex-direction: column; }
  .map-sidebar { width: 100%; max-height: 32vh; border-left: 0; border-top: 1px solid rgba(255,255,255,0.06); padding: 10px 14px; display: flex; gap: 8px; overflow-x: auto; }
  .region-card { min-width: 200px; margin-bottom: 0; }
  .map-canvas-wrap { padding: 8px; }
  .map-legend { display: none; }
  #hud-top-left { width: 34vw; gap: 7px; }
  .quest-card { padding: 8px 10px; }
  .quest-objective { font-size: 0.55rem; }
  .quest-title { font-size: 0.72rem; }
  .region-badge small { display: none; }
  #hud-bottom-left { width: 33vw; }
  .companion-chip { display: none; }
  .player-plate { padding: 6px 8px; }
  .player-avatar { width: 32px; height: 32px; }
  .action-button { width: 48px; height: 48px; }
  .action-button.attack { width: 74px; height: 74px; }
  .action-button.heavy { width: 56px; height: 56px; }
  .action-button.utility { width: 46px; height: 46px; }
  .action-button.potion { width: 38px; height: 38px; }
  .action-cluster { gap: 6px; }
  #actions { right: calc(14px + var(--safe-right)); bottom: calc(12px + var(--safe-bottom)); }
  #joystick { width: 120px; height: 120px; left: calc(14px + var(--safe-left)); bottom: calc(14px + var(--safe-bottom)); }
  .joystick-knob { width: 44px; height: 44px; margin: -22px; }
  #interaction-prompt { bottom: calc(94px + var(--safe-bottom)); font-size: 0.6rem; }
  .minimap-wrap { width: 96px; }
  .hud-menu-buttons .icon-button { width: 30px; height: 30px; }
  .boss-bar { width: 42vw; }
  .ending-content { transform: scale(0.92); }
}

@media (orientation: portrait) and (max-width: 1000px) {
  #rotate-screen { display: flex; }
}

@media (prefers-reduced-motion: reduce) {
  #grain { animation: none; }
}

import {
  APPEARANCE, ORIGINS, WEAPONS, ARMORS, CHARMS, CREATURES, MAIN_STAGES,
  SIDE_QUESTS, LORE, REGIONS, SKILLS, STAT_DEFS, SETTINGS_KEY, ENDINGS, formatTime,
} from './data.js';

const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const DEFAULT_SETTINGS = {
  music: 0.55,
  sfx: 0.8,
  quality: 'auto',
  fontScale: 1,
  reduceMotion: false,
  highContrast: false,
  damageNumbers: true,
  autoTarget: true,
  screenShake: true,
  leftHanded: false,
};

let svgUid = 0;

function portraitSVG(kind = 'player', appearance = {}, options = {}) {
  const uid = `p${++svgUid}`;
  const presets = {
    lyra: { skin: '#e8bd9d', hair: '#dbe7ee', outfit: '#40356b', accent: '#c6b7ff', style: 'largo', eye: '#7ee8fa', name: 'Lyra' },
    nima: { skin: '#b97a54', hair: '#5b3522', outfit: '#2f6a57', accent: '#b8f59e', style: 'trenza', eye: '#d7ffc7', name: 'Nima' },
    mira: { skin: '#d6a57f', hair: '#dbe7ee', outfit: '#6b3e4a', accent: '#f4d58d', style: 'largo', eye: '#c2a36b', name: 'Mira' },
    orin: { skin: '#8a5638', hair: '#241d2e', outfit: '#5d3e32', accent: '#ffb347', style: 'rapado', eye: '#f4d58d', name: 'Orin' },
    kael: { skin: '#c58a5e', hair: '#241d2e', outfit: '#4a2228', accent: '#ff8a4a', style: 'corto', eye: '#ffd166', name: 'Kael' },
    vex: { skin: '#d8d2e8', hair: '#e9e5f7', outfit: '#282143', accent: '#ffd166', style: 'largo', eye: '#fff2c4', name: 'Vex' },
    player: {
      skin: appearance.skinColor || '#e2b184',
      hair: appearance.hairColor || '#241d2e',
      outfit: appearance.outfitColor || '#2e5877',
      accent: appearance.accentColor || '#f4d58d',
      style: appearance.hairStyle || 'corto',
      eye: '#b9e7ff',
      name: appearance.name || 'Aurel',
    },
  };
  const p = presets[kind] || presets.player;
  const longHair = p.style === 'largo' || p.style === 'trenza';
  const hairBack = longHair
    ? `<path d="M50 112 C38 150 42 196 66 212 L134 212 C158 196 162 150 150 112 C142 142 58 142 50 112Z" fill="${p.hair}"/>`
    : '';
  const braid = p.style === 'trenza'
    ? `<path d="M143 145 C158 160 158 190 146 212" stroke="${p.hair}" stroke-width="14" fill="none" stroke-linecap="round"/>
       <path d="M143 177 l12 -4 M146 191 l11 2" stroke="${p.accent}" stroke-width="3" fill="none"/>`
    : '';
  const hairFront = p.style === 'rapado'
    ? `<path d="M62 105 C66 68 134 68 138 105 C124 90 76 90 62 105Z" fill="${p.hair}" opacity=".95"/>`
    : `<path d="M55 112 C52 72 78 52 100 52 C126 52 150 74 146 112 C136 92 126 83 111 80 C98 92 79 94 68 104 C64 108 60 111 55 112Z" fill="${p.hair}"/>
       <path d="M69 99 C81 75 118 73 135 96 C118 88 90 89 69 99Z" fill="${p.hair}" opacity=".8"/>`;
  const diadem = options.headgear === 'diadema' || kind === 'lyra' || kind === 'vex'
    ? `<path d="M61 88 Q100 70 139 88" stroke="${p.accent}" stroke-width="3" fill="none"/>
       <path d="M100 76 l7 10 -7 10 -7 -10Z" fill="${p.accent}"/>`
    : '';
  const helmet = options.headgear === 'celada'
    ? `<path d="M55 104 C55 68 80 48 100 48 C122 48 146 68 146 104 L142 128 L130 128 L126 98 C112 88 88 88 74 98 L70 128 L58 128Z" fill="${p.accent}"/>
       <path d="M100 60 L100 122 M76 108 L124 108" stroke="#2a2630" stroke-width="4"/>`
    : '';
  const freckles = kind === 'nima'
    ? `<g fill="#8f5c40" opacity=".65"><circle cx="79" cy="144" r="1.8"/><circle cx="86" cy="148" r="1.5"/><circle cx="118" cy="144" r="1.7"/><circle cx="124" cy="148" r="1.4"/></g>`
    : '';
  const scar = kind === 'kael'
    ? `<path d="M121 126 L132 151" stroke="#a9534a" stroke-width="2.5" opacity=".85"/>`
    : '';
  const halo = kind === 'vex'
    ? `<ellipse cx="100" cy="42" rx="42" ry="10" stroke="${p.accent}" stroke-width="2" fill="none" opacity=".85"/>
       <ellipse cx="100" cy="42" rx="30" ry="6" stroke="${p.accent}" stroke-width="1" fill="none" opacity=".4"/>`
    : '';
  const mask = kind === 'vex'
    ? `<path d="M64 124 Q100 105 136 124 Q130 166 100 174 Q70 166 64 124Z" fill="#f1e6d4" opacity=".96"/>
       <path d="M78 136 Q90 130 96 138 Q86 144 78 136Z" fill="${p.accent}"/>
       <path d="M122 136 Q110 130 104 138 Q114 144 122 136Z" fill="${p.accent}"/>
       <path d="M92 154 Q100 160 108 154" stroke="#7b5a3b" stroke-width="2" fill="none"/>`
    : '';
  return `
  <svg viewBox="0 0 200 240" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(p.name)}">
    <defs>
      <radialGradient id="${uid}bg" cx="50%" cy="34%" r="75%">
        <stop offset="0%" stop-color="${p.accent}" stop-opacity=".22"/>
        <stop offset="55%" stop-color="#0c1830" stop-opacity=".92"/>
        <stop offset="100%" stop-color="#050912"/>
      </radialGradient>
      <linearGradient id="${uid}out" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${p.outfit}"/>
        <stop offset="100%" stop-color="#111526"/>
      </linearGradient>
      <linearGradient id="${uid}skin" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${p.skin}"/>
        <stop offset="100%" stop-color="${shade(p.skin, -18)}"/>
      </linearGradient>
      <filter id="${uid}glow"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
    </defs>
    <rect width="200" height="240" fill="url(#${uid}bg)"/>
    <circle cx="100" cy="118" r="88" fill="none" stroke="${p.accent}" stroke-opacity=".12"/>
    <circle cx="100" cy="118" r="70" fill="none" stroke="${p.accent}" stroke-opacity=".06"/>
    ${halo}
    <path d="M28 240 C30 196 60 174 100 174 C140 174 170 196 172 240Z" fill="url(#${uid}out)"/>
    <path d="M66 180 C74 168 126 168 134 180 L130 220 L70 220Z" fill="${p.accent}" opacity=".22"/>
    <path d="M82 158 L118 158 L122 186 L78 186Z" fill="url(#${uid}skin)"/>
    ${hairBack}
    <path d="M64 116 C64 84 80 66 100 66 C120 66 136 84 136 116 L132 148 C128 174 112 184 100 184 C88 184 72 174 68 148Z" fill="url(#${uid}skin)"/>
    <path d="M66 120 C58 116 58 130 64 134 L69 134Z" fill="${shade(p.skin, -12)}"/>
    <path d="M134 120 C142 116 142 130 136 134 L131 134Z" fill="${shade(p.skin, -12)}"/>
    ${hairFront}
    ${diadem}
    ${helmet}
    ${mask}
    ${!mask ? `
    <path d="M78 122 Q88 116 96 122" stroke="#3b2a28" stroke-width="2.2" fill="none" stroke-linecap="round"/>
    <path d="M104 122 Q112 116 122 122" stroke="#3b2a28" stroke-width="2.2" fill="none" stroke-linecap="round"/>
    <ellipse cx="87" cy="130" rx="7" ry="5.5" fill="#fff8ec"/>
    <ellipse cx="113" cy="130" rx="7" ry="5.5" fill="#fff8ec"/>
    <circle cx="88" cy="130" r="3.6" fill="${p.eye}"/>
    <circle cx="112" cy="130" r="3.6" fill="${p.eye}"/>
    <circle cx="88" cy="130" r="1.8" fill="#1b2230"/>
    <circle cx="112" cy="130" r="1.8" fill="#1b2230"/>
    <circle cx="89.5" cy="128.4" r=".9" fill="#fff"/>
    <circle cx="113.5" cy="128.4" r=".9" fill="#fff"/>
    <path d="M100 133 Q97 142 101 144" stroke="${shade(p.skin, -28)}" stroke-width="1.8" fill="none" stroke-linecap="round"/>
    <path d="M90 156 Q100 162 110 156" stroke="#8b4f51" stroke-width="2.2" fill="none" stroke-linecap="round"/>
    <path d="M84 151 Q92 154 99 152" stroke="#d9908a" stroke-width="2" fill="none" opacity=".3"/>
    ${freckles}
    ${scar}
    ` : ''}
    ${braid}
    <path d="M70 202 Q100 188 130 202" stroke="${p.accent}" stroke-width="2" fill="none" opacity=".65"/>
    <path d="M100 196 l6 8 -6 8 -6 -8Z" fill="${p.accent}" opacity=".9" filter="url(#${uid}glow)"/>
  </svg>`;
}

function creaturePortraitSVG(species) {
  const uid = `c${++svgUid}`;
