465:     // joystick
466:     const joystick = $('joystick');
467:     const knob = $('joystick-knob');
468:     const updateJoystick = (e) => {
469:       const rect = joystick.getBoundingClientRect();
470:       const cx = rect.left + rect.width / 2;
471:       const cy = rect.top + rect.height / 2;
472:       let dx = e.clientX - cx;
473:       let dy = e.clientY - cy;
474:       const max = rect.width * 0.32;
475:       const len = Math.hypot(dx, dy);
476:       if (len > max) {
477:         dx = (dx / len) * max;
478:         dy = (dy / len) * max;
479:       }
480:       knob.style.transform = `translate(${dx}px, ${dy}px)`;
481:       this.joystick.x = dx / max;
482:       this.joystick.y = dy / max;
483:       this.joystick.active = true;
484:     };
485:     joystick?.addEventListener('pointerdown', (e) => {
486:       e.preventDefault();
487:       joystick.setPointerCapture(e.pointerId);
488:       updateJoystick(e);
489:     });
490:     joystick?.addEventListener('pointermove', (e) => {
491:       if (!this.joystick.active) return;
492:       e.preventDefault();
493:       updateJoystick(e);
494:     });
495:     const resetJoystick = () => {
496:       this.joystick.x = 0;
497:       this.joystick.y = 0;
498:       this.joystick.active = false;
499:       knob.style.transform = 'translate(0px, 0px)';
500:     };
501:     joystick?.addEventListener('pointerup', resetJoystick);
502:     joystick?.addEventListener('pointercancel', resetJoystick);
