692:   getProfileStats() {
693:     const origin = ORIGINS.find((o) => o.id === this.profile.origin) || ORIGINS[0];
694:     const stats = {};
695:     for (const s of STAT_DEFS) stats[s.id] = 3 + (origin.bonuses[s.id] || 0) + (this.profile.allocation[s.id] || 0);
696:     const w = WEAPONS[this.profile.weapon] || WEAPONS.filo_aurora;
697:     const a = ARMORS[this.profile.armor] || ARMORS.tunica_viajero;
698:     return {
699:       stats,
700:       maxHp: Math.round(80 + stats.vitalidad * 8 + a.hp),
701:       maxMp: Math.round(40 + stats.resonancia * 6 + a.mp),
702:       maxSp: Math.round(60 + stats.resistencia * 5),
703:       attack: Math.round(8 + stats.fuerza * 2.2 + w.atk),
704:       defense: Math.round(3 + stats.defensa * 1.6 + stats.resistencia * 0.5 + a.def),
705:     };
706:   }
