773:   updateHUD(game, dt) {
774:     if (!game || !game.state) return;
775:     const s = game.state;
776:     const p = s.player;
777:     const stats = game.getStats();
778:     const hp = Math.max(0, Math.round(p.hp));
779:     const mp = Math.max(0, Math.round(p.mp));
780:     const sp = Math.max(0, Math.round(p.sp));
781:     if (this.hudCache.hp !== hp || this.hudCache.maxHp !== stats.maxHp) {
782:       $('hp-fill').style.width = `${Math.max(0, (hp / stats.maxHp) * 100)}%`;
783:       $('hp-text').textContent = `${hp} / ${stats.maxHp}`;
784:       this.hudCache.hp = hp;
785:       this.hudCache.maxHp = stats.maxHp;
786:     }
787:     if (this.hudCache.mp !== mp || this.hudCache.maxMp !== stats.maxMp) {
788:       $('mp-fill').style.width = `${Math.max(0, (mp / stats.maxMp) * 100)}%`;
789:       this.hudCache.mp = mp;
790:       this.hudCache.maxMp = stats.maxMp;
791:     }
792:     if (this.hudCache.sp !== sp || this.hudCache.maxSp !== stats.maxSp) {
793:       $('sp-fill').style.width = `${Math.max(0, (sp / stats.maxSp) * 100)}%`;
794:       this.hudCache.sp = sp;
795:       this.hudCache.maxSp = stats.maxSp;
796:     }
797:     const xpPct = Math.min(100, (p.xp / p.xpNext) * 100);
798:     if (this.hudCache.xp !== xpPct) {
799:       $('xp-fill').style.width = `${xpPct}%`;
800:       this.hudCache.xp = xpPct;
801:     }
802:     if (this.hudCache.level !== p.level) {
803:       $('hud-level').textContent = `Nv. ${p.level}`;
804:       $('hud-player-name').textContent = p.name;
805:       $('player-initial').textContent = p.name.charAt(0).toUpperCase();
806:       this.hudCache.level = p.level;
807:     }
808:     if (this.hudCache.region !== s.region) {
809:       $('region-name').textContent = REGIONS[s.region]?.name || 'AETHERIA';
810:       $('region-epithet').textContent = REGIONS[s.region]?.epithet || '';
811:       this.hudCache.region = s.region;
812:     }
813:     const q = game.getQuestInfo();
814:     const qKey = JSON.stringify(q);
815:     if (this.questCache !== qKey) {
816:       $('quest-kind').textContent = q.kind || 'MISIÓN PRINCIPAL';
817:       $('quest-step').textContent = q.step || 'I';
818:       $('quest-title').textContent = q.title || '';
819:       $('quest-objective').textContent = q.objective || '';
820:       const prog = $('quest-progress');
821:       if (q.total) {
822:         prog.classList.remove('hidden');
823:         $('quest-progress-fill').style.width = `${Math.min(100, (q.progress / q.total) * 100)}%`;
824:         $('quest-objective').textContent = `${q.objective} (${q.progress}/${q.total})`;
825:       } else {
826:         prog.classList.add('hidden');
827:       }
828:       this.questCache = qKey;
829:     }
830:     const active = s.creatures.find((c) => c.active);
831:     const activeKey = active ? `${active.id}:${active.level}` : 'none';
832:     if (this.hudCache.active !== activeKey) {
833:       if (active) {
834:         const species = CREATURES[active.id];
835:         $('companion-name').textContent = `${species.name} · Nv. ${active.level}`;
836:         $('companion-skill').textContent = species.skill.name;
837:       } else {
838:         $('companion-name').textContent = 'Sin eco activo';
