1482:       g.addColorStop(0, color);
1483:       g.addColorStop(1, '#07111f');
1484:       ctx.fillStyle = g;
1485:       ctx.fill();
1486:       ctx.strokeStyle = 'rgba(244,213,141,0.18)';
1487:       ctx.lineWidth = 1.5;
