1490:     };
1491:     drawLand(nodes.valdoria.x, nodes.valdoria.y, 150, 105, '#2d4b3c', 3);
1492:     drawLand(nodes.drakmor.x, nodes.drakmor.y, 128, 90, '#4a2727', 7);
1493:     drawLand(nodes.kansordore.x, nodes.kansordore.y, 120, 82, '#3d3b62', 11);
