1551:   drawMinimap(game) {
1552:     const canvas = $('minimap');
1553:     if (!canvas || !game.world) return;
1554:     const ctx = canvas.getContext('2d');
1555:     const w = canvas.width;
1556:     const h = canvas.height;
1557:     ctx.clearRect(0, 0, w, h);
1558:     const region = REGIONS[game.state.region];
1559:     const cx = w / 2;
1560:     const cy = h / 2;
1561:     const scale = (w / 2 - 10) / 96;
1562:     ctx.save();
1563:     ctx.beginPath();
1564:     ctx.arc(cx, cy, w / 2 - 3, 0, Math.PI * 2);
1565:     ctx.clip();
1566:     const bg = ctx.createRadialGradient(cx, cy, 4, cx, cy, w / 2);
1567:     bg.addColorStop(0, region.palette.mid);
1568:     bg.addColorStop(1, region.palette.low);
1569:     ctx.fillStyle = bg;
1570:     ctx.fillRect(0, 0, w, h);
1571:     // contour rings
1572:     ctx.strokeStyle = 'rgba(255,255,255,0.06)';
1573:     ctx.lineWidth = 1;
1574:     for (let i = 1; i < 4; i++) {
1575:       ctx.beginPath();
1576:       ctx.arc(cx, cy, (w / 2 - 8) * (i / 4), 0, Math.PI * 2);
1577:       ctx.stroke();
1578:     }
1579:     const project = (x, z) => ({ x: cx + x * scale, y: cy + z * scale });
1580:     // landmarks
1581:     for (const key of Object.keys(game.world.landmarks)) {
1582:       const l = game.world.landmarks[key];
1583:       if (typeof l.x !== 'number') continue;
1584:       const p = project(l.x, l.z);
1585:       ctx.fillStyle = 'rgba(244,213,141,.55)';
1586:       ctx.beginPath(); ctx.arc(p.x, p.y, 2.4, 0, Math.PI * 2); ctx.fill();
1587:     }
1588:     // enemies
1589:     for (const e of game.enemies) {
1590:       if (e.dead) continue;
1591:       const p = project(e.group.position.x, e.group.position.z);
1592:       if (Math.hypot(p.x - cx, p.y - cy) > w / 2 - 6) continue;
1593:       ctx.fillStyle = e.def.boss ? '#ff8a4a' : '#ff6b6b';
1594:       ctx.beginPath(); ctx.arc(p.x, p.y, e.def.boss ? 4 : 2.5, 0, Math.PI * 2); ctx.fill();
1595:     }
1596:     // creatures
1597:     for (const c of game.creatures) {
1598:       if (c.captured) continue;
1599:       const p = project(c.group.position.x, c.group.position.z);
1600:       if (Math.hypot(p.x - cx, p.y - cy) > w / 2 - 6) continue;
1601:       ctx.fillStyle = '#7ee8fa';
1602:       ctx.beginPath(); ctx.arc(p.x, p.y, 2.2, 0, Math.PI * 2); ctx.fill();
1603:     }
1604:     // npcs
1605:     for (const n of game.npcs) {
1606:       if (!n.group.visible) continue;
1607:       const p = project(n.group.position.x, n.group.position.z);
1608:       ctx.fillStyle = '#f4d58d';
1609:       ctx.beginPath(); ctx.arc(p.x, p.y, 2.8, 0, Math.PI * 2); ctx.fill();
1610:     }
1611:     // quest marker
1612:     if (game.world.questMarker?.visible) {
1613:       const q = game.world.questMarker.position;
1614:       const p = project(q.x, q.z);
1615:       ctx.strokeStyle = '#f4d58d';
1616:       ctx.lineWidth = 1.6;
1617:       ctx.beginPath();
1618:       ctx.moveTo(p.x, p.y - 6); ctx.lineTo(p.x + 4, p.y); ctx.lineTo(p.x, p.y + 6); ctx.lineTo(p.x - 4, p.y); ctx.closePath(); ctx.stroke();
1619:     }
1620:     // player
1621:     const pp = project(game.player.group.position.x, game.player.group.position.z);
1622:     ctx.save();
1623:     ctx.translate(pp.x, pp.y);
1624:     ctx.rotate(Math.PI - game.player.group.rotation.y);
1625:     ctx.fillStyle = '#fff3c4';
1626:     ctx.beginPath();
1627:     ctx.moveTo(0, -7); ctx.lineTo(4.5, 5); ctx.lineTo(0, 2.5); ctx.lineTo(-4.5, 5); ctx.closePath();
1628:     ctx.fill();
1629:     ctx.strokeStyle = '#0a1220';
1630:     ctx.lineWidth = 1;
1631:     ctx.stroke();
1632:     ctx.restore();
1633:     ctx.restore();
1634:     // ring
1635:     ctx.strokeStyle = 'rgba(244,213,141,.4)';
1636:     ctx.lineWidth = 2;
1637:     ctx.beginPath(); ctx.arc(cx, cy, w / 2 - 3, 0, Math.PI * 2); ctx.stroke();
1638:   }
