219: function shade(hex, amt) {
220:   const c = hex.replace('#', '');
221:   const num = parseInt(c.length === 3 ? c.split('').map((x) => x + x).join('') : c, 16);
222:   const r = Math.max(0, Math.min(255, (num >> 16) + amt));
223:   const g = Math.max(0, Math.min(255, ((num >> 8) & 0xff) + amt));
224:   const b = Math.max(0, Math.min(255, (num & 0xff) + amt));
225:   return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
226: }
