718:         <span class="stat-name" title="${esc(s.desc)}">${esc(s.name)}</span>
719:         <button data-stat="${s.id}" data-delta="-1" ${alloc <= 0 ? 'disabled' : ''} aria-label="Quitar ${esc(s.name)}">−</button>
720:         <span class="stat-value">${base + alloc}</span>
721:         <button data-stat="${s.id}" data-delta="1" ${used >= 6 ? 'disabled' : ''} aria-label="Añadir ${esc(s.name)}">+</button>
722:       </div>`;
723:     }).join('');
