1425:   drawWorldMap(game) {
1426:     const canvas = $('world-map');
1427:     if (!canvas) return;
1428:     const ctx = canvas.getContext('2d');
1429:     const w = canvas.width;
1430:     const h = canvas.height;
1431:     ctx.clearRect(0, 0, w, h);
1432:     const bg = ctx.createRadialGradient(w * 0.5, h * 0.45, 40, w * 0.5, h * 0.5, w * 0.7);
1433:     bg.addColorStop(0, '#12233c');
1434:     bg.addColorStop(0.6, '#081426');
1435:     bg.addColorStop(1, '#040a13');
1436:     ctx.fillStyle = bg;
1437:     ctx.fillRect(0, 0, w, h);
1438: 
1439:     // grid
1440:     ctx.strokeStyle = 'rgba(126,232,250,0.045)';
1441:     ctx.lineWidth = 1;
1442:     for (let x = 0; x < w; x += 45) {
1443:       ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
1444:     }
1445:     for (let y = 0; y < h; y += 45) {
1446:       ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
1447:     }
1448: 
1449:     const nodes = {
1450:       valdoria: { x: 250, y: 420 },
1451:       drakmor: { x: 500, y: 300 },
1452:       kansordore: { x: 690, y: 165 },
1453:     };
1454:     const paths = [['valdoria', 'drakmor'], ['drakmor', 'kansordore']];
1455:     ctx.setLineDash([6, 8]);
1456:     ctx.strokeStyle = 'rgba(244,213,141,0.3)';
1457:     ctx.lineWidth = 2;
1458:     for (const [a, b] of paths) {
1459:       ctx.beginPath();
1460:       const A = nodes[a];
1461:       const B = nodes[b];
1462:       ctx.moveTo(A.x, A.y);
1463:       ctx.quadraticCurveTo((A.x + B.x) / 2, Math.min(A.y, B.y) - 55, B.x, B.y);
1464:       ctx.stroke();
1465:     }
1466:     ctx.setLineDash([]);
1467: 
1468:     const drawLand = (cx, cy, rx, ry, color, seed) => {
1469:       ctx.save();
1470:       ctx.translate(cx, cy);
1471:       ctx.beginPath();
1472:       const rng = (n) => Math.sin(seed * 12.9898 + n * 78.233) * 43758.5453 % 1;
1473:       for (let i = 0; i <= 40; i++) {
1474:         const a = (i / 40) * Math.PI * 2;
1475:         const r = 0.82 + Math.abs(rng(i)) * 0.3;
1476:         const x = Math.cos(a) * rx * r;
1477:         const y = Math.sin(a) * ry * r;
1478:         if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
1479:       }
1480:       ctx.closePath();
1481:       const g = ctx.createRadialGradient(0, -ry * 0.2, 10, 0, 0, rx);
1482:       g.addColorStop(0, color);
1483:       g.addColorStop(1, '#07111f');
1484:       ctx.fillStyle = g;
1485:       ctx.fill();
1486:       ctx.strokeStyle = 'rgba(244,213,141,0.18)';
1487:       ctx.lineWidth = 1.5;
1488:       ctx.stroke();
1489:       ctx.restore();
1490:     };
1491:     drawLand(nodes.valdoria.x, nodes.valdoria.y, 150, 105, '#2d4b3c', 3);
1492:     drawLand(nodes.drakmor.x, nodes.drakmor.y, 128, 90, '#4a2727', 7);
1493:     drawLand(nodes.kansordore.x, nodes.kansordore.y, 120, 82, '#3d3b62', 11);
1494: 
1495:     const unlocked = game.state.unlockedRegions;
1496:     const current = game.state.region;
1497:     for (const id of ['valdoria', 'drakmor', 'kansordore']) {
1498:       const n = nodes[id];
1499:       const r = REGIONS[id];
1500:       const isUnlocked = unlocked.includes(id);
1501:       const isCurrent = id === current;
1502:       ctx.save();
1503:       ctx.translate(n.x, n.y);
1504:       if (isUnlocked) {
1505:         const pulse = 1 + Math.sin(performance.now() / 500 + n.x) * 0.08;
1506:         const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 44 * pulse);
1507:         glow.addColorStop(0, isCurrent ? 'rgba(244,213,141,0.42)' : 'rgba(126,232,250,0.22)');
1508:         glow.addColorStop(1, 'rgba(126,232,250,0)');
1509:         ctx.fillStyle = glow;
1510:         ctx.beginPath(); ctx.arc(0, 0, 44 * pulse, 0, Math.PI * 2); ctx.fill();
1511:       }
1512:       ctx.beginPath();
1513:       ctx.arc(0, 0, isCurrent ? 9 : 7, 0, Math.PI * 2);
1514:       ctx.fillStyle = isUnlocked ? (isCurrent ? '#f4d58d' : '#7ee8fa') : '#4e5869';
1515:       ctx.fill();
1516:       ctx.strokeStyle = isCurrent ? '#fff2c4' : 'rgba(255,255,255,.4)';
1517:       ctx.lineWidth = 2;
1518:       ctx.stroke();
1519:       ctx.font = '600 22px Cinzel, serif';
1520:       ctx.textAlign = 'center';
1521:       ctx.fillStyle = isUnlocked ? '#f5f0e6' : '#5d6678';
1522:       ctx.fillText(r.name, 0, 48);
1523:       ctx.font = '500 13px Manrope, sans-serif';
1524:       ctx.fillStyle = isUnlocked ? 'rgba(245,240,230,.6)' : 'rgba(93,102,120,.7)';
1525:       ctx.fillText(isCurrent ? 'ESTÁS AQUÍ' : isUnlocked ? 'DESBLOQUEADA' : 'BLOQUEADA', 0, 68);
1526:       if (!isUnlocked) {
1527:         ctx.font = '18px Manrope, sans-serif';
1528:         ctx.fillText('✦', 0, -18);
1529:       }
1530:       ctx.restore();
1531:     }
1532: 
1533:     // decorative compass
1534:     ctx.save();
1535:     ctx.translate(70, 70);
1536:     ctx.strokeStyle = 'rgba(244,213,141,.35)';
1537:     ctx.lineWidth = 1;
1538:     ctx.beginPath(); ctx.arc(0, 0, 26, 0, Math.PI * 2); ctx.stroke();
1539:     ctx.beginPath(); ctx.moveTo(0, -34); ctx.lineTo(0, 34); ctx.moveTo(-34, 0); ctx.lineTo(34, 0); ctx.stroke();
1540:     ctx.fillStyle = '#f4d58d';
1541:     ctx.font = '600 11px Cinzel, serif';
1542:     ctx.textAlign = 'center';
1543:     ctx.fillText('N', 0, -38);
1544:     ctx.restore();
1545:     ctx.fillStyle = 'rgba(244,213,141,.5)';
1546:     ctx.font = '500 11px Manrope, sans-serif';
1547:     ctx.textAlign = 'right';
1548:     ctx.fillText('AETHERIA · MAPA DEL VELO', w - 26, h - 22);
1549:   }
