280:       const tan = curve.getTangent(t).normalize();
281:       const nx = -tan.z;
282:       const nz = tan.x;
283:       const hw = width / 2;
284:       for (const s of [-1, 1]) {
285:         const x = pt.x + nx * hw * s;
286:         const z = pt.z + nz * hw * s;
287:         positions.push(x, this.heightAt(x, z) + 0.06, z);
288:       }
289:       if (i < segs) {
290:         const a = i * 2;
291:         indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
292:       }
293:     }
294:     const g = new THREE.BufferGeometry();
295:     g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
296:     g.setIndex(indices);
297:     g.computeVertexNormals();
