395: export function updatePlayerModel(model, dt, time) {
396:   const p = model.pose;
397:   const { bodyRoot, parts, materialsList } = model;
398:   p.time += dt;
399:   const t = p.time;
400:   const move = clamp(p.moving, 0, 1);
401:   const run = move * (p.sprinting ? 1.35 : 1);
402: 
403:   bodyRoot.position.y = 0;
404:   bodyRoot.position.x = 0;
405:   bodyRoot.position.z = 0;
406:   bodyRoot.rotation.set(0, 0, 0);
407: 
408:   // idle breathing
409:   const breathe = Math.sin(t * 2.1) * 0.012;
410:   bodyRoot.position.y = breathe;
411:   parts.torso.rotation.x = damp(parts.torso.rotation.x, 0.06 + run * 0.12, 8, dt);
412:   parts.torso.rotation.z = damp(parts.torso.rotation.z, -Math.sin(t * 8) * 0.025 * move, 8, dt);
413: 
414:   // legs and arms walk cycle
415:   const cycle = t * (p.sprinting ? 12 : 8.5);
416:   const swing = Math.sin(cycle) * 0.68 * run;
417:   parts.leftLeg.rotation.x = damp(parts.leftLeg.rotation.x, swing, 16, dt);
418:   parts.rightLeg.rotation.x = damp(parts.rightLeg.rotation.x, -swing, 16, dt);
419:   parts.leftLeg.rotation.z = 0;
420:   parts.rightLeg.rotation.z = 0;
421:   parts.leftArm.rotation.x = damp(parts.leftArm.rotation.x, -swing * 0.6 - 0.05, 14, dt);
422:   parts.rightArm.rotation.x = damp(parts.rightArm.rotation.x, swing * 0.45 - 0.08, 14, dt);
423:   parts.leftArm.rotation.z = damp(parts.leftArm.rotation.z, 0.08, 8, dt);
424:   parts.rightArm.rotation.z = damp(parts.rightArm.rotation.z, -0.08, 8, dt);
425:   parts.head.rotation.x = damp(parts.head.rotation.x, -run * 0.08, 8, dt);
426:   parts.head.rotation.z = damp(parts.head.rotation.z, Math.sin(t * 1.3) * 0.03 * (1 - move), 6, dt);
427:   parts.cape.rotation.x = damp(parts.cape.rotation.x, 0.05 + run * 0.42 + Math.sin(t * 5) * 0.05, 7, dt);
428:   parts.cape.rotation.z = Math.sin(t * 3.4) * 0.04;
429:   parts.shield.visible = false;
430:   parts.weapon.visible = true;
431:   parts.weapon.rotation.set(0.1, 0, -0.14);
432:   parts.weapon.position.set(0, -0.58, 0.03);
433: 
434:   // hurt flash
435:   if (p.hurt > 0) {
436:     p.hurt = Math.max(0, p.hurt - dt);
437:     const f = p.hurt * 8;
438:     bodyRoot.position.x = Math.sin(t * 75) * 0.045 * f;
439:     for (const m of materialsList) m.emissive?.setRGB(f * 0.55, f * 0.08, f * 0.04);
440:   } else {
441:     for (const m of materialsList) m.emissive?.setRGB(0, 0, 0);
442:   }
443: 
444:   if (p.dead) {
445:     p.deadProgress = Math.min(1, p.deadProgress + dt * 1.6);
446:     bodyRoot.rotation.x = -p.deadProgress * 1.35;
447:     bodyRoot.position.y = -p.deadProgress * 0.25;
448:     return;
449:   }
450: 
451:   if (p.dodging) {
452:     const q = clamp(p.dodgeProgress, 0, 1);
453:     bodyRoot.position.y = 0.45 + Math.sin(q * Math.PI) * 0.25;
454:     bodyRoot.rotation.x = q * TAU;
455:     parts.leftArm.rotation.x = -1.2;
456:     parts.rightArm.rotation.x = -1.2;
457:     return;
458:   }
459: 
460:   if (p.blocking) {
461:     parts.torso.rotation.x = damp(parts.torso.rotation.x, 0.22, 12, dt);
462:     parts.leftArm.rotation.x = damp(parts.leftArm.rotation.x, -1.25, 16, dt);
463:     parts.leftArm.rotation.z = damp(parts.leftArm.rotation.z, -0.45, 16, dt);
464:     parts.rightArm.rotation.x = damp(parts.rightArm.rotation.x, -0.7, 12, dt);
465:     parts.rightArm.rotation.z = damp(parts.rightArm.rotation.z, 0.3, 12, dt);
466:     parts.shield.visible = true;
467:     const pulse = 1 + Math.sin(t * 8) * 0.04;
468:     parts.shield.scale.setScalar(pulse);
469:     return;
470:   }
471: 
472:   if (p.casting) {
473:     const q = clamp(p.castProgress, 0, 1);
474:     const lift = Math.sin(q * Math.PI);
475:     parts.leftArm.rotation.x = damp(parts.leftArm.rotation.x, -2.2 * lift, 18, dt);
476:     parts.rightArm.rotation.x = damp(parts.rightArm.rotation.x, -2.2 * lift, 18, dt);
477:     parts.leftArm.rotation.z = damp(parts.leftArm.rotation.z, -0.6 * lift, 18, dt);
478:     parts.rightArm.rotation.z = damp(parts.rightArm.rotation.z, 0.6 * lift, 18, dt);
479:     parts.torso.rotation.x = damp(parts.torso.rotation.x, -0.1 * lift, 10, dt);
480:     parts.head.rotation.x = damp(parts.head.rotation.x, -0.2 * lift, 10, dt);
481:     parts.weapon.visible = false;
482:     return;
483:   }
484: 
485:   if (p.attacking) {
486:     const q = clamp(p.attackProgress, 0, 1);
487:     const windup = Math.min(1, q / 0.34);
488:     const strike = q < 0.34 ? 0 : Math.min(1, (q - 0.34) / 0.28);
489:     const recover = q < 0.62 ? 0 : (q - 0.62) / 0.38;
490:     const combo = p.combo % 3;
491:     const dir = combo === 1 ? -1 : 1;
492:     let armX = -0.5 - windup * 1.5 + strike * 2.5 - recover * 0.8;
493:     let armZ = dir * (-0.35 - windup * 0.85 + strike * 2.15 - recover * 0.7);
494:     let bodyYaw = dir * (-0.45 * windup + strike * 1.25 - recover * 0.8);
495:     if (p.attackType === 'heavy') {
496:       armX = -1.9 + windup * 0.2 + strike * 2.6 - recover * 0.7;
497:       armZ = -0.9 * windup + strike * 1.9 - recover * 0.9;
498:       bodyYaw = -0.55 * windup + strike * 1.15 - recover * 0.6;
499:     }
500:     parts.rightArm.rotation.x = damp(parts.rightArm.rotation.x, armX, 26, dt);
501:     parts.rightArm.rotation.z = damp(parts.rightArm.rotation.z, armZ, 26, dt);
502:     parts.leftArm.rotation.x = damp(parts.leftArm.rotation.x, -0.35 - strike * 0.4, 14, dt);
503:     parts.leftArm.rotation.z = damp(parts.leftArm.rotation.z, 0.18, 12, dt);
504:     parts.torso.rotation.y = damp(parts.torso.rotation.y, bodyYaw, 24, dt);
505:     parts.torso.rotation.x = damp(parts.torso.rotation.x, 0.08 + strike * 0.12, 18, dt);
506:     parts.head.rotation.y = damp(parts.head.rotation.y, bodyYaw * 0.5, 18, dt);
507:     parts.cape.rotation.x = damp(parts.cape.rotation.x, 0.18 + strike * 0.55, 10, dt);
508:     return;
509:   }
510: 
511:   parts.torso.rotation.y = damp(parts.torso.rotation.y, 0, 10, dt);
512:   parts.head.rotation.y = damp(parts.head.rotation.y, 0, 10, dt);
513: }
