515: export function rebuildPlayerModel(oldModel, appearance, weaponId, armorId, headgear) {
516:   const next = buildPlayer(appearance, weaponId, armorId, headgear);
517:   next.group.position.copy(oldModel.group.position);
518:   next.group.rotation.copy(oldModel.group.rotation);
519:   next.pose = oldModel.pose;
520:   return next;
521: }
