527: function addEyes(group, count, spread, y, z, color, size = 0.05) {
528:   const m = new THREE.MeshBasicMaterial({ color });
529:   for (let i = 0; i < count; i++) {
530:     const e = sphere(size, m, 6);
531:     const off = count === 1 ? 0 : (i - (count - 1) / 2) * spread;
532:     e.position.set(off, y, z);
533:     group.add(e);
534:     addGlow(group, color, size * 6, [off, y, z + 0.02], 0.55);
535:   }
536: }
